nk"]},{"nr":5,"slot":"BRA","slot_name":"Hammer-Curls","rolle":"acc","uebung_id":"L10","uebung":"Hammer-Curls","saetze":3,"wdh":"12-20","einheit":"wdh","pro_seite":false,"pause":"60–90 Sek","pause_sek":75,"hinweis":"Neutraler Griff, Ellbogen fix, langsam ablassen.","technik":null,"benoetigt":["kurzhanteln"]},{"nr":6,"slot":"CORE_ROT","slot_name":"Rumpf: Anti-Rotation / seitlich","rolle":"core","uebung_id":"H33","uebung":"Band-Pallof-Press","saetze":3,"wdh":"12-20","einheit":"wdh","pro_seite":true,"pause":"45–60 Sek","pause_sek":50,"hinweis":"Band seitlich auf Brusthöhe, Arme nach vorn strecken, Oberkörper nicht verdrehen.","technik":null,"benoetigt":["baender","tuer"]}],"dauer_min_geschaetzt":55},"BB":{"id":"BB","name":"Beine B","uebungen":[{"nr":1,"slot":"HINGE","slot_name":"Hüftbeugen (Hinge)","rolle":"main","uebung_id":"H25","uebung":"Kurzhantel-Rumänisches Kreuzheben","saetze":4,"wdh":"6-10","einheit":"wdh","pro_seite":false,"pause":"2–3 Min","pause_sek":150,"hinweis":"Hüfte nach hinten, Hanteln nah am Bein, Rücken gerade.","technik":"Tempo 3-1-1 (3 Sek ablassen, 1 Sek Pause unten)","benoetigt":["kurzhanteln"]},{"nr":2,"slot":"QUAD2","slot_name":"Zweite Quadrizeps-Übung","rolle":"sec","uebung_id":"A4","uebung":"Bulgarian Split Squat (Kurzhantel)","saetze":3,"wdh":"8-12","einheit":"wdh","pro_seite":true,"pause":"90–120 Sek","pause_sek":105,"hinweis":"Hinterer Fuß auf der Bank, Oberkörper leicht nach vorn.","technik":null,"benoetigt":["kurzhanteln","bank"]},{"nr":3,"slot":"GLUTE","slot_name":"Po (Hip Thrust)","rolle":"sec","uebung_id":"H26","uebung":"Kurzhantel-Hip-Thrust","saetze":3,"wdh":"8-12","einheit":"wdh","pro_seite":false,"pause":"90–120 Sek","pause_sek":105,"hinweis":"Schultern auf der Bank, Hantel auf der Hüfte (Handtuch drunter), oben Po fest.","technik":null,"benoetigt":["kurzhanteln","bank"]},{"nr":4,"slot":"QISO","slot_name":"Quadrizeps-Isolation","rolle":"acc","uebung_id":"BW64","uebung":"Sissy Squat (am Türrahmen)","saetze":3,"wdh":"12-20","einheit":"wdh","pro_seite":false,"pause":"60–90 Sek","pause_sek":75,"hinweis":"Festhalten, auf die Zehen, Knie nach vorn, Oberkörper zurück – nur schmerzfrei.","technik":null,"benoetigt":[],"stufen":[{"stufe":1,"uebung_id":"BW63","name":"Wandsitzen","wdh":"30-60","hinweis":"Oberschenkel parallel zum Boden, Rücken flach an der Wand."},{"stufe":2,"uebung_id":"BW64","name":"Sissy Squat (am Türrahmen)","wdh":"12-20","hinweis":"Festhalten, auf die Zehen, Knie nach vorn, Oberkörper zurück – nur schmerzfrei."},{"stufe":3,"uebung_id":"BW65","name":"Reverse Nordic (Teilbewegung)","wdh":"6-10","hinweis":"Kniend auf Kissen, Oberkörper gerade nach hinten lehnen."}],"start_stufe":2},{"nr":5,"slot":"HCURL","slot_name":"Beinbeuger","rolle":"acc","uebung_id":"BW67","uebung":"Gleitende Beinbeuger (einbeinig)","saetze":3,"wdh":"12-20","einheit":"wdh","pro_seite":true,"pause":"60–90 Sek","pause_sek":75,"hinweis":"Ein Bein angehoben, Hüfte bleibt oben.","technik":null,"benoetigt":["handtuch","glatter_boden"],"stufen":[{"stufe":1,"uebung_id":"BW66","name":"Gleitende Beinbeuger (beidbeinig)","wdh":"12-20","hinweis":"Rückenlage, Fersen auf Handtuch, Hüfte oben halten, Fersen zum Po ziehen."},{"stufe":2,"uebung_id":"BW67","name":"Gleitende Beinbeuger (einbeinig)","wdh":"12-20","hinweis":"Ein Bein angehoben, Hüfte bleibt oben."},{"stufe":3,"uebung_id":"BW68","name":"Nordic Curl (negativ)","wdh":"3-6 (so langsam wie möglich)","hinweis":"Füße unter Sofa fixiert, so langsam wie möglich nach vorn absenken, Hände fangen ab."}],"start_stufe":2},{"nr":6,"slot":"CALF","slot_name":"Waden","rolle":"acc","uebung_id":"H27","uebung":"Einbeiniges Kurzhantel-Wadenheben","saetze":3,"wdh":"12-20","einheit":"wdh","pro_seite":true,"pause":"60–90 Sek","pause_sek":75,"hinweis":"Auf Stufe, freie Hand hält sich fest, unten volle Dehnung.","technik":null,"benoetigt":["kurzhanteln","stufe"]}],"dauer_min_geschaetzt":55},"AE":{"id":"AE","name":"Aktive Erholung","uebungen":[{"nr":1,"slot":"CARDIO","slot_name":"Ausdauer (Zone 2)","rolle":"cardio","uebung_id":"C1","uebung":"Lockeres Joggen oder Radfahren (Zone 2)","saetze":1,"wdh":"20-30","einheit":"min","pro_seite":false,"pause":"–","pause_sek":0,"hinweis":"Tempo, bei dem du noch in ganzen Sätzen sprechen kannst.","technik":null,"benoetigt":[]},{"nr":2,"slot":"MOB","slot_name":"Mobility","rolle":"mob","uebung_id":"M1","uebung":"Mobility-Routine","saetze":1,"wdh":"15","einheit":"min","pro_seite":false,"pause":"–","pause_sek":0,"hinweis":"Hüfte, Brustwirbelsäule, Schultern, Sprunggelenke – ruhig, ohne Schmerz.","technik":null,"benoetigt":[]}],"dauer_min_geschaetzt":55}},"sequenz":[{"tag":1,"woche":1,"typ":"training","vorlage":"PA"},{"tag":2,"woche":1,"typ":"training","vorlage":"ZA"},{"tag":3,"woche":1,"typ":"training","vorlage":"BA"},{"tag":4,"woche":1,"typ":"training","vorlage":"PB"},{"tag":5,"woche":1,"typ":"training","vorlage":"ZB"},{"tag":6,"woche":1,"typ":"training","vorlage":"BB"},{"tag":7,"woche":1,"typ":"aktive_erholung","vorlage":"AE"},{"tag":8,"woche":2,"typ":"training","vorlage":"PA"},{"tag":9,"woche":2,"typ":"training","vorlage":"ZA"},{"tag":10,"woche":2,"typ":"training","vorlage":"BA"},{"tag":11,"woche":2,"typ":"training","vorlage":"PB"},{"tag":12,"woche":2,"typ":"training","vorlage":"ZB"},{"tag":13,"woche":2,"typ":"training","vorlage":"BB"},{"tag":14,"woche":2,"typ":"aktive_erholung","vorlage":"AE"},{"tag":15,"woche":3,"typ":"training","vorlage":"PA"},{"tag":16,"woche":3,"typ":"training","vorlage":"ZA"},{"tag":17,"woche":3,"typ":"training","vorlage":"BA"},{"tag":18,"woche":3,"typ":"training","vorlage":"PB"},{"tag":19,"woche":3,"typ":"training","vorlage":"ZB"},{"tag":20,"woche":3,"typ":"training","vorlage":"BB"},{"tag":21,"woche":3,"typ":"aktive_erholung","vorlage":"AE"},{"tag":22,"woche":4,"typ":"training","vorlage":"PA"},{"tag":23,"woche":4,"typ":"training","vorlage":"ZA"},{"tag":24,"woche":4,"typ":"training","vorlage":"BA"},{"tag":25,"woche":4,"typ":"training","vorlage":"PB"},{"tag":26,"woche":4,"typ":"training","vorlage":"ZB"},{"tag":27,"woche":4,"typ":"training","vorlage":"BB"},{"tag":28,"woche":4,"typ":"aktive_erholung","vorlage":"AE"},{"tag":29,"woche":5,"typ":"training","vorlage":"PA"},{"tag":30,"woche":5,"typ":"training","vorlage":"ZA"},{"tag":31,"woche":5,"typ":"training","vorlage":"BA"},{"tag":32,"woche":5,"typ":"training","vorlage":"PB"},{"tag":33,"woche":5,"typ":"training","vorlage":"ZB"},{"tag":34,"woche":5,"typ":"training","vorlage":"BB"},{"tag":35,"woche":5,"typ":"aktive_erholung","vorlage":"AE"}]}$pl$::jsonb)
