INSERT INTO content_docs (doc_id, tier_min, daten)
SELECT doc_id, tier_min, daten
FROM (VALUES
  ('mental_module', 2, $cd${"tier":2,"freischaltung":"Standard: alle 3 Tage ein neues Modul in der Reihenfolge 'reihenfolge' (Tag 1, 4, 7 …). Zusätzlich können Regeln aus Tier 3 ein Modul früher freischalten (Feld mental_modul in regeln.json).","hinweis_zitate":"Alle Texte sind eigenständig formuliert. Konzepte wie 40-Prozent-Regel, Accountability Mirror und Cookie Jar werden David Goggins zugeschrieben, aber nicht wörtlich zitiert.","module":[{"id":"M10","tier":2,"titel":"Ich weiß nicht, wo ich anfangen soll","untertitel":"Die kleinste Version, die trotzdem zählt","reihenfolge":1,"umfrage_bezug":"Ich weiß nicht, wo ich anfangen soll","freischalt_trigger":"start","woerter":365,"lesezeit_min":2,"datei":"texte/01_m10_ich_weiss_nicht_wo_ich_anfangen_soll.md","text":"Du willst etwas ändern. Training, Schlaf, Handy, Schule, Zimmer, alles gleichzeitig. Und genau deshalb passiert nichts. Wenn alles wichtig ist, fühlt sich jeder einzelne Schritt zu klein an und der ganze Berg zu groß. Also bleibst du am Fuß stehen.\n\nEinige Teilnehmer der unbroken-Umfrage haben genau das als größtes Hindernis genannt. Das ist ehrlicher, als viele denken: Nicht fehlender Wille hält dich auf, sondern Überforderung.\n\nDie Lösung ist fast peinlich einfach. Fang mit der kleinsten Version an, die sich trotzdem wie ein echter Schritt anfühlt. Und mach genau eine Sache.\n\nWarum klein? Weil Anfangen der schwerste Teil ist und weil jedes erledigte Mini-Ziel dein Vertrauen in dich selbst stärkt. Die Psychologie nennt das Selbstwirksamkeit: Du glaubst eher, dass du etwas schaffst, wenn du schon etwas Ähnliches geschafft hast. Große Pläne, die nach drei Tagen scheitern, bewirken das Gegenteil, sie beweisen dir, dass du es nicht kannst. Kleine Schritte, die du wirklich machst, beweisen dir, dass du es kannst.\n\nSo findest du deinen Startpunkt:\n\n**Wähle einen Bereich.** Nur einen. Wenn du hier bist, ist es wahrscheinlich Training. Dann ist das dein Bereich für die nächsten vier Wochen. Alles andere darf warten.\n\n**Lass dir die Entscheidungen abnehmen.** Du musst nicht wissen, welche Übungen, wie viele Sätze, welcher Split. Dafür ist dein Plan da. Dein Job: auftauchen und ausführen.\n\n**Definiere, was „geschafft“ heißt.** Nicht „ich trainiere mehr“, sondern „ich mache die drei Einheiten dieser Woche“. Ein Ziel, das du am Sonntag mit Ja oder Nein beantworten kannst.\n\n**Mach den Start lächerlich leicht.** Die erste Woche geht nicht darum, an deine Grenze zu gehen. Sie geht darum, die Übungen kennenzulernen, Technik zu lernen und zu merken: Ich kann das. Die Gewichte kommen von selbst.\n\n**Erst wenn es läuft, kommt das Nächste.** Wenn Training nach ein paar Wochen fester Teil deiner Woche ist, nimmst du dir den nächsten Bereich vor, zum Beispiel Schlaf. Nicht vorher.\n\nViele glauben, sie bräuchten erst den perfekten Plan, bevor sie loslegen dürfen. Die Wahrheit: Der perfekte Plan, den du nicht startest, ist schlechter als ein guter Plan, den du heute anfängst. Und der liegt schon vor dir.\n\n**Heute:** Öffne deinen Plan, schau dir die erste Einheit an und leg fest, wann genau du sie machst."},{"id":"M05","tier":2,"titel":"Motivation ist Wetter, Disziplin ist ein System","untertitel":"Warum du aufhören solltest, auf den richtigen Moment zu warten","reihenfolge":2,"umfrage_bezug":"Motivation fehlt","freischalt_trigger":"start","woerter":360,"lesezeit_min":2,"datei":"texte/02_m05_motivation_ist_wetter_disziplin_ist_ein_.md","text":"In der Umfrage, auf der unbroken aufbaut, war „Motivation fehlt“ eine der beiden häufigsten Antworten auf die Frage nach dem größten Hindernis. Das ist ehrlich. Und es ist gleichzeitig der Grund, warum so viele Pläne scheitern: Sie bauen auf etwas, das von Natur aus unzuverlässig ist.\n\nMotivation ist ein Gefühl. Gefühle schwanken. Sie hängen davon ab, wie du geschlafen hast, was in der Schule los war, ob dich jemand genervt hat. Wer nur trainiert, wenn er motiviert ist, trainiert an guten Tagen. Gute Tage sind selten genug, dass daraus nie etwas wird.\n\nDas Gegenmittel ist nicht mehr Motivation. Es ist ein System, das auch an schlechten Tagen funktioniert.\n\nDie Forschung zu Gewohnheiten zeigt: Menschen, die langfristig dranbleiben, haben nicht mehr Willenskraft als andere. Sie müssen sie nur seltener einsetzen, weil ihr Verhalten an feste Auslöser gekoppelt ist. Gleiche Zeit, gleicher Ort, gleicher Ablauf. Irgendwann läuft es, ohne dass man jedes Mal neu entscheidet. Und jede Entscheidung, die du nicht treffen musst, ist eine Gelegenheit weniger, dich rauszureden.\n\nSo baust du dieses System:\n\n**Feste Zeiten statt „irgendwann heute“.** Dein Training steht im Kalender wie ein Termin. Dienstag, 17 Uhr. Nicht verhandelbar außer bei echten Notfällen.\n\n**Vorbereitung am Vorabend.** Tasche gepackt, Klamotten raus, Plan angeschaut. Je weniger Schritte zwischen dir und dem Training liegen, desto weniger Platz für Ausreden.\n\n**Die Zwei-Minuten-Regel.** An Tagen, an denen gar nichts geht, ist dein einziger Auftrag: umziehen und die erste Übung anfangen. Mehr nicht. Meistens machst du danach weiter, weil Anfangen der schwerste Teil ist. Und wenn nicht, hast du die Gewohnheit trotzdem geschützt.\n\n**Keine Entscheidungen im Moment.** Was du trainierst, wie viele Sätze, welches Gewicht: steht im Plan. Du musst nicht nachdenken, nur ausführen. Genau dafür ist er da.\n\nDas heißt nicht, dass Motivation wertlos ist. Sie ist großartig, aber als Starthilfe. Nutze sie, wenn sie da ist, um dein System zu bauen: Zeiten festlegen, Ausrüstung besorgen, Plan einrichten. Verlass dich nur nicht darauf, dass sie morgen wieder vorbeikommt.\n\nDisziplin klingt nach eiserner Willenskraft. In Wahrheit ist sie meistens etwas viel Unspektakuläreres: ein Ablauf, den du nicht mehr in Frage stellst.\n\n**Heute:** Trag deine Trainingszeiten für die nächste Woche mit Uhrzeit in deinen Kalender ein."},{"id":"M01","tier":2,"titel":"Die 40-Prozent-Regel","untertitel":"Dein erstes „Ich kann nicht mehr“ ist selten das letzte","reihenfolge":3,"umfrage_bezug":"Motivation fehlt","freischalt_trigger":"start","woerter":377,"lesezeit_min":2,"datei":"texte/03_m01_die_40_prozent_regel.md","text":"Du kennst den Moment. Dritter Satz, die Arme brennen, und irgendwo im Kopf meldet sich eine Stimme: Das reicht. Du hast genug gemacht. Niemand merkt, wenn du jetzt aufhörst.\n\nDie 40-Prozent-Regel geht auf David Goggins zurück. Die Idee: Wenn dein Kopf das erste Mal „Schluss“ ruft, bist du nicht am Ende deiner Möglichkeiten, sondern ungefähr bei 40 Prozent davon. Die Zahl ist kein Messwert. Niemand hat im Labor ausgerechnet, dass es genau 40 sind. Sie ist ein Bild für etwas, das die Sportwissenschaft tatsächlich beobachtet: Die Wahrnehmung von Anstrengung bremst dich meistens früher als dein Körper.\n\nIm psychobiologischen Modell der Ausdauerleistung wird genau das beschrieben. Menschen hören oft nicht auf, weil die Muskeln physisch nicht mehr können, sondern weil die empfundene Anstrengung zu hoch wird. Und diese Empfindung hängt von vielem ab: Müdigkeit im Kopf, Stimmung, Erwartung, ob dir jemand zuschaut. Das heißt, sie ist beeinflussbar. Du kannst lernen, mehr davon auszuhalten.\n\nDein Gehirn ist ein Sicherheitsbeauftragter mit deutlich zu viel Vorsicht. Es will Energie sparen und Unangenehmes vermeiden. Früher war das überlebenswichtig. Im Gym sorgt es dafür, dass du Sätze beendest, obwohl noch zwei saubere Wiederholungen drin gewesen wären.\n\nSo wendest du die Regel an, ohne dich zu ruinieren:\n\n**Unterscheide unangenehm von gefährlich.** Brennen im Muskel, schwerer Atem, der Wunsch aufzuhören: unangenehm. Stechender Schmerz im Gelenk, Schwindel, Druck in der Brust, Taubheit: gefährlich. Beim Ersten machst du weiter. Beim Zweiten hörst du sofort auf. Keine Diskussion. Härte, die dich verletzt, ist keine Disziplin, sondern Dummheit mit gutem Marketing.\n\n**Technik ist die Grenze.** Wenn die Wiederholung nur noch mit Schwung, Hohlkreuz oder halbem Bewegungsweg geht, ist der Satz vorbei. Die Regel heißt nicht, Fehler zu wiederholen, bis etwas reißt.\n\n**Verhandle nicht mitten im Satz.** Entscheide vorher, wie viele Wiederholungen du machst. Wenn die Stimme kommt, hat sie nichts mehr zu entscheiden, weil die Entscheidung längst gefallen ist.\n\n**Nutze die Regel außerhalb des Gyms.** Beim Lernen, beim Aufstehen, bei der Aufgabe, die du seit Tagen wegschiebst. Das erste „keine Lust“ ist fast nie die Wahrheit. Es ist ein Vorschlag. Und Vorschläge darf man ablehnen.\n\n**Heute:** Achte in der nächsten Einheit auf den Moment, in dem dein Kopf zum ersten Mal „genug“ sagt. Registriere ihn. Dann zieh die geplanten Wiederholungen trotzdem sauber durch. Du wirst merken: Da war mehr."},{"id":"M02","tier":2,"titel":"Der Accountability Mirror","untertitel":"Ehrlichkeit, die unangenehm ist","reihenfolge":4,"umfrage_bezug":"Motivation fehlt","freischalt_trigger":"start","woerter":370,"lesezeit_min":2,"datei":"texte/04_m02_der_accountability_mirror.md","text":"Es gibt eine Übung, die nichts kostet, fünf Minuten dauert und trotzdem von den meisten vermieden wird: dir selbst die Wahrheit sagen.\n\nDer Accountability Mirror ist ein Konzept, das David Goggins bekannt gemacht hat. In seiner Version kleben Zettel am Badezimmerspiegel: Ziele, Schwächen, unbequeme Wahrheiten. Jeden Tag schaut er sie an. Nicht, um sich fertigzumachen, sondern um sich nicht mehr belügen zu können.\n\nWarum das funktioniert: Wir sind Meister darin, uns die eigene Geschichte schönzureden. „Ich hatte keine Zeit.“ „Das Training war eh nicht so wichtig.“ „Ab Montag.“ In der Psychologie heißt das Selbstrechtfertigung. Wir passen unsere Erklärung an unser Verhalten an, damit wir uns besser fühlen. Das Problem: Was du dir schönredest, kannst du nicht verbessern.\n\nForschung zur Selbstbeobachtung zeigt seit Jahrzehnten, dass Menschen ihr Verhalten eher ändern, wenn sie es regelmäßig und ehrlich festhalten. Nicht das Gefühl zählt, sondern der Fakt. Genau das macht der Spiegel: Er ersetzt „lief eigentlich ganz okay“ durch „von vier geplanten Einheiten habe ich zwei gemacht“.\n\nSo baust du deinen eigenen:\n\n**Schritt 1 – Drei Zettel.** Einer mit einem konkreten Ziel für die nächsten vier Wochen. Einer mit der Schwäche, die dich am meisten davon abhält. Einer mit deiner häufigsten Ausrede.\n\n**Schritt 2 – Sichtbar aufhängen.** Spiegel, Schreibtisch, innen in der Handyhülle. Es geht nicht um Deko, es geht um Konfrontation.\n\n**Schritt 3 – Einmal pro Woche Bilanz.** Drei Fragen, schriftlich: Was habe ich wirklich gemacht? Wo habe ich mich rausgeredet? Was mache ich nächste Woche anders? Zahlen statt Gefühle.\n\nEine wichtige Grenze: Ehrlich heißt nicht grausam. Der Spiegel ist kein Ort, um dich zu beleidigen. „Ich bin ein Versager“ ist keine Analyse, sondern Lärm. „Ich habe Dienstag und Donnerstag ausgelassen, weil ich abends zu lange am Handy war“ ist eine Analyse. Damit kannst du arbeiten. Studien zu Selbstmitgefühl zeigen sogar, dass Menschen, die nach Fehlern fair mit sich umgehen, sich danach mehr anstrengen, nicht weniger. Harte Standards und ein fairer Blick auf dich selbst sind kein Widerspruch. Sie gehören zusammen.\n\nDer Spiegel wirkt nur, wenn du ihn benutzt, wenn es unangenehm ist. Die Woche, in der du am wenigsten hinschauen willst, ist die Woche, in der du ihn am meisten brauchst.\n\n**Heute:** Schreib deine drei Zettel. Ziel, Schwäche, Lieblingsausrede. Häng sie auf."},{"id":"M03","tier":2,"titel":"Das Cookie Jar","untertitel":"Beweise gegen die Stimme, die sagt, dass du es nicht kannst","reihenfolge":5,"umfrage_bezug":"Motivation fehlt","freischalt_trigger":"start","woerter":364,"lesezeit_min":2,"datei":"texte/05_m03_das_cookie_jar.md","text":"Wenn es hart wird, erinnert sich dein Kopf bevorzugt an eines: an alles, was schiefgelaufen ist. Die Male, an denen du aufgegeben hast. Die Pläne, die nach zwei Wochen versandet sind. Das ist kein Zufall. Das Gehirn gewichtet Negatives stärker als Positives, Psychologen nennen das Negativitätsverzerrung.\n\nDas Cookie Jar ist das Gegenmittel. Die Idee stammt von David Goggins: eine gedachte Keksdose, in der jeder harte Moment liegt, den du überstanden hast. Wenn du aufgeben willst, greifst du hinein und erinnerst dich: Das hier habe ich schon geschafft. Also schaffe ich auch das.\n\nDahinter steckt mehr als ein nettes Bild. In der Psychologie heißt das Prinzip Selbstwirksamkeit: der Glaube, dass du eine Aufgabe durch eigenes Handeln bewältigen kannst. Albert Bandura hat gezeigt, dass die stärkste Quelle dafür eigene Erfolgserlebnisse sind. Nicht Motivationsvideos, nicht Zuspruch von anderen, sondern: Ich habe es selbst gemacht. Das Cookie Jar macht diese Erlebnisse abrufbar, genau dann, wenn du sie brauchst.\n\nWas gehört rein? Keine Heldentaten. Die meisten Einträge sind klein:\n\n- die Einheit, die du gemacht hast, obwohl du keine Lust hattest\n- der erste saubere Klimmzug\n- die Woche ohne Ausfall\n- die Prüfung, für die du gelernt hast, statt zu zocken\n- der Moment, in dem du Nein gesagt hast, obwohl alle anderen Ja gesagt haben\n\nEs zählt nicht, wie beeindruckend etwas für andere klingt. Es zählt, dass es für dich schwer war und du es trotzdem gemacht hast.\n\nSo setzt du es um: Leg eine Notiz an, auf Papier oder im Handy. Schreib heute drei Einträge rein, auch wenn sie dir klein vorkommen. Jeder Eintrag bekommt ein Datum, was du gemacht hast und warum es schwer war. Ab jetzt kommt alles rein, was du durchziehst, obwohl es dir schwerfällt. Sofort, nicht irgendwann.\n\nUnd dann der wichtigste Teil: Lies es. Vor einem harten Training. Nach einem schlechten Tag. Wenn die Stimme sagt, dass du das eh nicht durchhältst. Du wirst schwarz auf weiß sehen, dass sie schon oft falschlag.\n\nEin Hinweis: Das Cookie Jar ist kein Ort zum Angeben und kein Vergleich mit anderen. Es ist deine private Beweissammlung. Je ehrlicher die Einträge, desto stärker wirken sie.\n\n**Heute:** Drei Einträge. Mindestens einer davon aus den letzten sieben Tagen."},{"id":"M07","tier":2,"titel":"Wenn-Dann-Pläne","untertitel":"Entscheide jetzt, was du später machst","reihenfolge":6,"umfrage_bezug":"Impulskontrolle / schädliche Gewohnheiten","freischalt_trigger":"start","woerter":367,"lesezeit_min":2,"datei":"texte/06_m07_wenn_dann_plaene.md","text":"Gute Vorsätze scheitern selten an fehlendem Wissen. Du weißt, dass du trainieren solltest. Du weißt, dass du früher schlafen solltest. Sie scheitern im Moment der Entscheidung, wenn du müde bist, abgelenkt, oder die Couch einfach bequemer ist.\n\nEine der am besten untersuchten Methoden der Verhaltenspsychologie setzt genau dort an: Wenn-Dann-Pläne, in der Forschung Implementation Intentions genannt. Statt „Ich will mehr trainieren“ formulierst du: „Wenn es Dienstag 17 Uhr ist, dann packe ich meine Tasche und gehe los.“ Eine große Auswertung von Peter Gollwitzer und Paschal Sheeran über fast hundert Studien kam zu dem Ergebnis, dass solche Pläne die Chance deutlich erhöhen, ein Ziel tatsächlich umzusetzen, spürbar mehr als das Ziel allein.\n\nWarum das funktioniert: Du nimmst die Entscheidung aus dem Moment heraus. Dein Gehirn speichert die Verbindung zwischen Situation und Handlung. Tritt die Situation ein, ist die Handlung schon vorbereitet, fast wie ein Reflex. Du musst nicht mehr abwägen, ob du Lust hast, weil du längst entschieden hast.\n\nÜbrigens arbeitet unbroken im Hintergrund genauso. Der Plan hat feste Regeln, die automatisch greifen, wenn bestimmte Situationen eintreten. Du kannst dasselbe für dein Leben außerhalb des Trainings bauen.\n\nSo formulierst du gute Wenn-Dann-Pläne:\n\n**Konkret, nicht vage.** „Wenn ich Zeit habe“ ist kein Auslöser. „Wenn ich von der Schule komme und meine Tasche abstelle“ schon. Der Auslöser muss eine Situation sein, die du eindeutig erkennst.\n\n**Eine Handlung, kein Gefühl.** „Dann bin ich motiviert“ funktioniert nicht. „Dann ziehe ich meine Trainingsklamotten an“ funktioniert.\n\n**Für Hindernisse, nicht nur für Ziele.** Die stärksten Pläne sind die für deine typischen Stolpersteine: „Wenn ich merke, dass ich nach 22 Uhr noch scrolle, dann lege ich das Handy auf den Schreibtisch und stehe auf.“ „Wenn ein Freund fragt, ob ich statt Training zocken will, dann sage ich: nach dem Training.“ „Wenn ich eine Einheit verpasse, dann mache ich die nächste am Folgetag, ohne Diskussion.“\n\n**Wenige, aber gute.** Drei bis fünf Pläne für deine wichtigsten Situationen schlagen zwanzig, die du vergisst.\n\n**Schriftlich.** Aufschreiben verstärkt den Effekt. Noch besser: dort aufhängen, wo die Situation eintritt.\n\nDas Beste daran: Wenn-Dann-Pläne brauchen keine Motivation. Sie ersetzen sie durch Vorbereitung.\n\n**Heute:** Schreib drei Wenn-Dann-Pläne auf. Einen fürs Training, einen für deinen größten Stolperstein, einen für den Tag nach einem verpassten Training."},{"id":"M04","tier":2,"titel":"Verpasste Tage","untertitel":"Einmal ist ein Ausrutscher, zweimal ist ein Muster","reihenfolge":7,"umfrage_bezug":"Rückschläge nach guten Phasen","freischalt_trigger":"verpasster_tag","woerter":333,"lesezeit_min":2,"datei":"texte/07_m04_verpasste_tage.md","text":"Irgendwann verpasst du ein Training. Nicht vielleicht, sondern sicher. Krankheit, Klausur, Familienfeier, ein Tag, an dem einfach nichts geht. Die Frage ist nicht, ob es passiert. Die Frage ist, was du am Tag danach machst.\n\nHier sterben die meisten Pläne. Nicht am verpassten Tag selbst, sondern an dem Gedanken danach: „Jetzt ist es eh egal.“ Die Woche ist ruiniert, die Serie ist weg, also kann man auch gleich bis Montag warten. Und aus Montag wird der Montag danach.\n\nDie Psychologie hat einen Namen dafür: den Abstinenz-Verletzungs-Effekt, salopp der „Jetzt-ist-es-auch-egal-Effekt“. Wer sich strenge Alles-oder-nichts-Regeln setzt, gibt nach einem einzigen Fehler oft komplett auf, weil sich der Fehler wie ein Beweis anfühlt, dass man es nicht kann. Der Fehler selbst ist klein. Die Reaktion darauf ist das Problem.\n\nGleichzeitig zeigt eine bekannte Untersuchung zur Gewohnheitsbildung vom University College London: Einzelne ausgelassene Tage hatten kaum Einfluss darauf, ob sich eine Gewohnheit festigt. Was zählt, ist die Linie über Wochen, nicht die perfekte Serie. Ein verpasster Tag löscht deinen Fortschritt nicht. Zehn verpasste Tage, weil du nach dem ersten aufgegeben hast, schon.\n\nDie Regel ist deshalb einfach: **nie zweimal hintereinander.**\n\nEinmal verpassen kann jedem passieren und sagt nichts über dich aus. Zweimal hintereinander ist der Anfang einer neuen Gewohnheit, nur leider der falschen.\n\nSo gehst du konkret damit um:\n\n**Kein Nachholen im Doppelpack.** Du machst nicht zwei Einheiten an einem Tag, um Schuld abzuarbeiten. Du machst einfach die nächste. Dein Plan wartet, die Einheit bleibt offen, bis du sie erledigst.\n\n**Kurze Analyse, kein Drama.** War es unvermeidbar (krank, Notfall) oder eine Ausrede? Beides ist okay zu wissen. Nur das Zweite musst du ändern.\n\n**Die nächste Einheit wird geschützt.** Uhrzeit festlegen, Tasche packen, jemandem Bescheid sagen. Der Tag nach einem Ausfall ist der wichtigste Trainingstag der Woche.\n\n**Krank ist krank.** Fieber, Infekt, Verletzung: Das ist kein Disziplin-Test. Training mit Fieber ist gefährlich. Dann ist Erholung der Plan.\n\n**Heute:** Wenn gestern oder vorgestern etwas ausgefallen ist, ist heute der Tag. Es muss keine perfekte Einheit sein. Nur eine erledigte."},{"id":"M06","tier":2,"titel":"Impulskontrolle","untertitel":"Warum Willenskraft allein verliert","reihenfolge":8,"umfrage_bezug":"Impulskontrolle / schädliche Gewohnheiten","freischalt_trigger":"start","woerter":360,"lesezeit_min":2,"datei":"texte/08_m06_impulskontrolle.md","text":"Impulskontrolle und schädliche Gewohnheiten waren in der unbroken-Umfrage genauso häufig wie fehlende Motivation. Endlos scrollen, zocken bis spät in die Nacht, Dinge tun, von denen du weißt, dass sie dir nicht guttun. Nicht, weil du schwach bist, sondern weil du gegen einen Gegner antrittst, der auf deine Schwachstellen optimiert wurde.\n\nViele Apps und Spiele sind gezielt so gebaut, dass sie deine Aufmerksamkeit halten: endlose Feeds, Belohnungen in unregelmäßigen Abständen, Benachrichtigungen, die dich zurückholen. Dagegen mit reiner Willenskraft anzukämpfen ist wie Tauziehen gegen einen Traktor.\n\nForschung zur Selbstkontrolle zeigt etwas Überraschendes: Menschen mit besonders guter Selbstkontrolle widerstehen Versuchungen nicht besser. Sie geraten seltener in Situationen, in denen sie widerstehen müssen. Sie gestalten ihre Umgebung so, dass die Versuchung gar nicht erst auftaucht. Das ist keine Schwäche, das ist Strategie.\n\nDie wirksamsten Hebel:\n\n**Reibung erhöhen.** Mach schlechte Gewohnheiten umständlich. Handy nachts außerhalb des Zimmers laden. Apps vom Startbildschirm in einen Ordner auf der letzten Seite. Controller nach dem Zocken in den Schrank. Jede Sekunde zwischen dir und dem Impuls gibt deinem Verstand eine Chance, sich einzuschalten.\n\n**Reibung senken, wo du sie nicht willst.** Sporttasche an der Tür, Trainingsplan als erster Tab, Wasserflasche auf dem Schreibtisch.\n\n**Den Impuls aussitzen.** Ein Drang fühlt sich an, als würde er immer stärker, bis du nachgibst. Tut er nicht. Impulse steigen an, erreichen einen Höhepunkt und flauen wieder ab, meist in wenigen Minuten. Wenn der Drang kommt: Timer auf zehn Minuten, beobachten, nicht handeln. Danach ist er oft deutlich schwächer.\n\n**Ersetzen statt nur streichen.** Eine Gewohnheit, die du einfach weglässt, hinterlässt eine Lücke, und die füllt sich schnell wieder mit dem Alten. Überleg dir, was du stattdessen machst. Langeweile um 22 Uhr? Dann liegt dort ein Buch statt des Handys.\n\n**Auslöser kennen.** Schreib eine Woche lang auf, wann dich der Impuls erwischt: Uhrzeit, Ort, Stimmung. Meistens gibt es ein Muster, oft Müdigkeit, Langeweile oder Stress nach der Schule. Wenn du den Auslöser kennst, kannst du einen Plan für genau diesen Moment machen (siehe Wenn-Dann-Pläne).\n\nDu musst nicht alles auf einmal ändern. Eine Gewohnheit, eine Maßnahme.\n\n**Heute:** Such dir die eine Gewohnheit aus, die dich am meisten kostet, und erhöhe heute die Reibung dafür mit einer konkreten Änderung."},{"id":"M11","tier":2,"titel":"Keine Zeit? Die ehrliche Rechnung","untertitel":"Warum du weniger brauchst, als du denkst","reihenfolge":9,"umfrage_bezug":"Zu wenig Zeit","freischalt_trigger":"start","woerter":335,"lesezeit_min":2,"datei":"texte/09_m11_keine_zeit_die_ehrliche_rechnung.md","text":"„Zu wenig Zeit“ gehört zu den häufigsten Gründen, nicht zu trainieren. Manchmal stimmt das: Schule, Hausaufgaben, Nebenjob, Familie. Oft ist „keine Zeit“ aber eine Abkürzung für „keine Priorität“ oder „keine Energie“. Beides ist okay zuzugeben. Nur dann kannst du es lösen.\n\nZuerst die gute Nachricht: Du brauchst weniger Zeit, als du denkst. Untersuchungen zum Muskelaufbau zeigen, dass schon zwei bis drei Einheiten pro Woche zuverlässig Fortschritte bringen, wenn die Sätze hart genug sind. Entscheidend ist nicht, wie lange du im Gym bist, sondern wie viele wirklich anstrengende Sätze du machst. Eine konzentrierte Einheit von 40 Minuten schlägt zwei Stunden mit Handy zwischen den Sätzen.\n\nDie ehrliche Rechnung: Mach eine Woche lang ein Zeitprotokoll. Nicht geschätzt, sondern notiert. Vor allem die Bildschirmzeit, die dein Handy dir direkt anzeigt. Viele sind überrascht, dass dort zwei, drei, vier Stunden pro Tag stehen. Es geht nicht darum, dir das zu verbieten. Es geht darum zu sehen, wo deine Zeit wirklich ist.\n\nDann die Strategien:\n\n**Weniger Tage, dafür fest.** Drei Einheiten, die sicher stattfinden, schlagen fünf, die du halb machst. Der 3-Tage-Ganzkörperplan ist genau dafür gebaut und trifft jede Muskelgruppe mehrmals pro Woche.\n\n**Kürzere Einheiten.** Wenn du in deinem Profil ein kleines Zeitbudget angibst, passt sich dein Plan an: Zusatzübungen fallen weg, Grundübungen bleiben. Du trainierst dann das, was den größten Effekt hat.\n\n**Supersätze.** Zwei Übungen für gegensätzliche Muskeln im Wechsel, zum Beispiel Drücken und Ziehen. Während der eine Muskel arbeitet, erholt sich der andere. Das spart Pausenzeit, ohne die Wirkung zu verlieren.\n\n**Handy weg zwischen den Sätzen.** Timer stellen, Pause einhalten, weitermachen. Das allein spart oft zehn bis fünfzehn Minuten pro Einheit.\n\n**Training als Termin.** Wer trainiert, „wenn Zeit ist“, hat nie Zeit. Wer Dienstag 17 Uhr im Kalender stehen hat, findet sie.\n\nEine Grenze gibt es: Schlaf ist keine Zeitreserve. Wer sich Trainingszeit vom Schlaf abzwackt, verliert beim Muskelaufbau mehr, als er gewinnt. Nimm die Zeit lieber vom Bildschirm.\n\n**Heute:** Schau in deine Bildschirmzeit der letzten Woche. Nimm eine halbe Stunde davon und trag sie als Trainingszeit ein."},{"id":"M08","tier":2,"titel":"Wenn dein Umfeld dich bremst","untertitel":"Freunde, Spott und die Leute, die nichts ändern wollen","reihenfolge":10,"umfrage_bezug":"Umfeld / Freunde bremsen mich","freischalt_trigger":"start","woerter":365,"lesezeit_min":2,"datei":"texte/10_m08_wenn_dein_umfeld_dich_bremst.md","text":"Ein erheblicher Teil der unbroken-Umfrage hat angegeben: Mein Umfeld bremst mich. Freunde, die lieber chillen. Leute, die Sprüche machen, wenn du früher gehst, weil du morgen trainierst. Eine Gruppe, in der sich niemand verändert und die es komisch findet, wenn du es tust.\n\nDas ist kein Einzelfall. Menschen passen sich ihrem Umfeld an, oft ohne es zu merken. Wir übernehmen Gewohnheiten, Einstellungen und Ziele von denen, mit denen wir die meiste Zeit verbringen. Das kann dich hochziehen oder festhalten.\n\nWichtig vorab: Du musst deine Freunde nicht abschreiben. Wer dich bremst, ist nicht automatisch ein schlechter Mensch. Oft ist es einfach eure gemeinsame Routine. Wenn du dich veränderst, fühlt sich das für andere manchmal wie Kritik an, auch wenn du es nicht so meinst.\n\nWas funktioniert:\n\n**Erklär nicht zu viel.** Du musst niemanden überzeugen. „Ich trainiere gerade, ich bin um 22 Uhr raus“ reicht. Je mehr du dich rechtfertigst, desto mehr Angriffsfläche bietest du.\n\n**Plane um, statt abzusagen.** Du musst auf nichts verzichten. Triff deine Leute nach dem Training statt stattdessen. Das Training ist fix, der Rest passt sich an.\n\n**Lade ein, dränge nicht.** Manchmal will jemand mitmachen, sobald er sieht, dass du es ernst meinst. Frag einmal. Wenn nicht, ist das okay. Leute zum Training zu überreden funktioniert selten.\n\n**Such dir zusätzlich Leute, die in dieselbe Richtung gehen.** Das muss deine Freundesgruppe nicht ersetzen. Ein Trainingspartner, eine Community, ein Kumpel, der auch etwas aufbaut. In der Umfrage war „Austausch mit Leuten, die dasselbe durchmachen“ nach dem klaren Wochenplan die meistgenannte Hilfe. Eine einzige Person, die dasselbe durchzieht wie du, macht einen großen Unterschied.\n\n**Behalte Spott im Verhältnis.** Wenn dich jemand dafür auslacht, dass du an dir arbeitest, sagt das mehr über ihn als über dich. Das heißt nicht, dass es nicht nervt. Es heißt nur, dass du nicht verpflichtet bist, für andere kleiner zu bleiben.\n\nUnd wenn es ernster ist: Wenn Menschen in deinem Umfeld dich regelmäßig zu Dingen drängen, die dir wirklich schaden, oder dich systematisch runtermachen, ist das kein Disziplinproblem mehr. Dann ist es klug, mit jemandem zu reden, dem du vertraust: Familie, Lehrer, ein älterer Freund.\n\n**Heute:** Überleg, wer in deinem Umfeld dich unterstützt, und schreib dieser Person, was du gerade vorhast."},{"id":"M12","tier":2,"titel":"Freiwillig schwer","untertitel":"Warum du Unbequemlichkeit trainieren solltest","reihenfolge":11,"umfrage_bezug":"Impulskontrolle / schädliche Gewohnheiten","freischalt_trigger":"start","woerter":368,"lesezeit_min":2,"datei":"texte/11_m12_freiwillig_schwer.md","text":"Die meisten Menschen bauen ihr Leben so, dass es möglichst bequem ist. Aufzug statt Treppe, Lieferdienst statt kochen, Handy sofort, wenn es langweilig wird. Verständlich. Aber es hat einen Preis: Wer nie etwas Unbequemes macht, für den wird alles Unbequeme riesig.\n\nDavid Goggins beschreibt das mit dem Bild eines Kopfes, der Hornhaut bekommt, so wie Hände durch harte Arbeit widerstandsfähiger werden. Wer sich regelmäßig freiwillig Unangenehmem aussetzt, gewöhnt sich daran, und die nächste schwierige Situation wirft ihn nicht mehr so leicht um.\n\nAuch die Forschung kennt dieses Prinzip, unter anderen Namen. Untersuchungen zur Stressbewältigung deuten darauf hin, dass dosierte, bewältigbare Herausforderungen die Belastbarkeit stärken können, während ein Leben ganz ohne Widerstand eher empfindlicher macht. Wichtig ist das Wort dosiert: Es geht um Herausforderungen, die du selbst wählst und die du bewältigen kannst.\n\nFreiwillig ist der entscheidende Unterschied zwischen Training und Leiden. Wenn dir das Leben etwas Schweres vor die Füße wirft, hast du keine Wahl. Wenn du dir selbst etwas Schweres suchst, übst du für diesen Moment, unter Bedingungen, die du kontrollierst.\n\nKleine, sichere Beispiele für den Alltag:\n\n- Treppe statt Aufzug, jedes Mal\n- die letzten 30 Sekunden der Dusche kalt, wenn du gesund bist\n- die unangenehmste Aufgabe des Tages zuerst erledigen\n- etwas anfangen, bei dem du am Anfang schlecht bist: ein Instrument, eine Sprache, eine neue Übung\n- ein unangenehmes Gespräch führen, statt es ewig aufzuschieben\n- beim Training den letzten Satz sauber zu Ende bringen, obwohl dein Kopf früher aufhören will\n\nNichts davon ist heldenhaft. Genau darum geht es. Du sammelst jeden Tag kleine Beweise, dass du Unangenehmes aushältst. Und jedes Mal wird die Stimme, die „zu anstrengend“ sagt, ein bisschen leiser.\n\nWas es nicht ist: Selbstbestrafung. Unbequemlichkeit trainieren heißt nicht, dir Schlaf zu entziehen, Mahlzeiten ausfallen zu lassen, verletzt zu trainieren oder dich zu quälen, um dir etwas zu beweisen. Das macht dich nicht stärker, sondern kaputt. Die Herausforderung soll dich wachsen lassen, nicht beschädigen.\n\nUnd noch etwas: Freiwillig schwer heißt nicht, Erholung zu verachten. Die härtesten Athleten nehmen Schlaf und Ruhetage ernster als alle anderen, weil sie wissen, dass Belastung nur wirkt, wenn Erholung folgt.\n\n**Heute:** Such dir eine kleine freiwillige Unbequemlichkeit aus und mach sie, bevor der Tag vorbei ist."},{"id":"M13","tier":2,"titel":"Schmerz ist nicht gleich Schmerz","untertitel":"Wann Härte klug ist und wann sie dumm wird","reihenfolge":12,"umfrage_bezug":"Sicherheit","freischalt_trigger":"start","woerter":380,"lesezeit_min":2,"datei":"texte/12_m13_schmerz_ist_nicht_gleich_schmerz.md","text":"In der Grind-Kultur wird viel über Schmerz geredet: durchziehen, Zähne zusammenbeißen, nicht jammern. Das hat seinen Platz. Aber es gibt einen Punkt, an dem Härte nicht stark ist, sondern dumm. Wer den nicht erkennt, trainiert irgendwann gar nicht mehr, weil er verletzt ist.\n\nDie wichtigste Fähigkeit im Training ist deshalb nicht, Schmerz zu ignorieren, sondern ihn richtig zu lesen.\n\n**Normal – weitermachen:** Brennen im Muskel gegen Ende eines Satzes. Schwerer Atem, Herzklopfen bei harter Belastung. Muskelkater ein bis drei Tage danach, dumpf und großflächig. Allgemeine Erschöpfung nach einer harten Einheit. Das alles heißt nur, dass du deinen Körper gefordert hast.\n\n**Warnsignale – sofort aufhören:** Stechender, scharfer Schmerz, besonders in Gelenken wie Knie, Schulter, Ellbogen oder im unteren Rücken. Schmerz, der plötzlich während einer Wiederholung auftritt, vielleicht mit einem Knacken. Taubheit, Kribbeln oder Kraftverlust, der nicht zur Anstrengung passt. Schwindel, Übelkeit, Druck oder Schmerz in der Brust, Atemnot, die nicht nachlässt. Schmerz, der auf einer Seite deutlich stärker ist als auf der anderen.\n\nBei diesen Signalen ist der Satz vorbei, meistens auch die Einheit. Das ist keine Schwäche, das ist Intelligenz.\n\n**Was danach zu tun ist:** Wenn eine Übung wehtut, weich auf eine schmerzfreie Alternative aus. unbroken hat für jede Übung Varianten. Melde den Schmerz in der App, dann wird die Übung getauscht und nicht weiter gesteigert. Wenn Schmerzen nach etwa einer Woche nicht deutlich besser sind, wenn sie nachts oder in Ruhe auftreten oder ein Gelenk anschwillt: zum Arzt oder zur Physiotherapie. Nicht googeln, nicht aussitzen.\n\nWarum das so wichtig ist: Eine kleine Reizung, die du eine Woche schonst, ist in einer Woche vorbei. Dieselbe Reizung, die du mit „Zähne zusammenbeißen“ weiter belastest, kann dich Monate kosten. Wer dauerhaft stark sein will, muss zuerst dauerhaft trainieren können.\n\nNoch ein Wort zur Technik: Die meisten Trainingsverletzungen entstehen nicht durch zu viel Härte, sondern durch zu viel Gewicht bei schlechter Ausführung. Gerade wenn du noch lernst, ist saubere Technik wichtiger als jede Zahl auf der Hantel. Lieber zwei Kilo weniger und jede Wiederholung sauber als ein Ego-Satz, der dich Wochen kostet.\n\nDie härteste Entscheidung im Training ist manchmal nicht, weiterzumachen, sondern aufzuhören, wenn es der richtige Moment ist, obwohl alle anderen weitermachen.\n\n**Heute:** Geh deinen Körper kurz durch. Zwickt irgendwo etwas seit Längerem? Dann nutze in der nächsten Einheit die Alternativübung dafür."},{"id":"M09","tier":2,"titel":"Die Falle nach der guten Phase","untertitel":"Warum es oft genau dann kippt, wenn es läuft","reihenfolge":13,"umfrage_bezug":"Rückschläge nach guten Phasen","freischalt_trigger":"comeback","woerter":374,"lesezeit_min":2,"datei":"texte/13_m09_die_falle_nach_der_guten_phase.md","text":"Es läuft. Drei, vier Wochen am Stück trainiert, du fühlst dich stark, alles sitzt. Und dann bricht es weg. Eine Woche ausgelassen, dann zwei. Plötzlich fühlt es sich an, als wärst du wieder bei null.\n\nRückschläge nach guten Phasen waren in der unbroken-Umfrage ein eigener Punkt, und sie gehören zu den frustrierendsten Erfahrungen überhaupt, weil sie sich wie Verrat anfühlen. Du dachtest, du hättest es endlich geschafft.\n\nMeist steckt eine von vier Ursachen dahinter:\n\n**Die Anfangsenergie ist aufgebraucht.** Am Anfang trägt dich das Neue. Nach ein paar Wochen ist der Reiz weg und Training wird Routine. Genau dort muss ein System übernehmen. Wenn keins da ist, fällt alles zusammen.\n\n**Das Leben ändert sich.** Prüfungsphase, Ferien, Krankheit, Stress zu Hause. Deine Routine hing an einem bestimmten Alltag, und der ist plötzlich weg.\n\n**Du hast überdreht.** In guten Phasen legen viele noch einen drauf: Extra-Einheiten, mehr Gewicht, weniger Schlaf. Der Körper macht das eine Weile mit und stellt dann die Rechnung.\n\n**Du hast die Sicherheitsnetze abgebaut.** Weil es so gut lief, hast du aufgehört, die Tasche am Vorabend zu packen, Zeiten einzutragen, Bilanz zu ziehen. Genau die Gewohnheiten, die dich in die gute Phase gebracht haben, fallen weg, und mit ihnen die Phase.\n\nWas dagegen hilft:\n\n**Erwarte den Einbruch.** Fortschritt verläuft nie als gerade Linie. Wer weiß, dass nach vier guten Wochen oft eine schwierige kommt, erschrickt nicht, wenn sie kommt. Sie ist kein Beweis, dass du es nicht kannst, sondern ein normaler Teil des Wegs.\n\n**Bau die Netze nicht ab.** Gerade in guten Phasen: Plan nutzen, Zeiten eintragen, Wochenbilanz machen. Kostet wenig, fängt dich auf, wenn es kippt.\n\n**Leg jetzt deine Minimalversion fest.** Was machst du in einer Prüfungswoche oder nach einer Erkältung mindestens? Zum Beispiel zwei kurze Einheiten statt vier. Die Linie wird nicht unterbrochen, sie wird nur dünner.\n\n**Nicht mehr als geplant.** Deload-Wochen und Ruhetage sind kein Vorschlag. Wer in guten Phasen überzieht, zahlt später.\n\nUnd falls es schon passiert ist: Der Rückschlag löscht nicht, was du aufgebaut hast. Kraft und Muskulatur bleiben über Wochen erstaunlich stabil, und der Wiederaufbau geht deutlich schneller als der erste Aufbau. Du fängst nicht bei null an, du fängst mit Erfahrung an.\n\n**Heute:** Schreib deine Minimalversion auf – was machst du in einer richtig schlechten Woche mindestens?"},{"id":"M14","tier":2,"titel":"Werde jemand, der nicht verhandelt","untertitel":"Identität schlägt Ziele","reihenfolge":14,"umfrage_bezug":"Motivation fehlt","freischalt_trigger":"start","woerter":375,"lesezeit_min":2,"datei":"texte/14_m14_werde_jemand_der_nicht_verhandelt.md","text":"Es gibt zwei Arten, ein Ziel zu formulieren. Die erste: „Ich will dreimal pro Woche trainieren.“ Die zweite: „Ich bin jemand, der trainiert.“ Klingt nach Wortspielerei, ist es nicht.\n\nWer über Ergebnisse denkt, stellt sich jeden Tag die Frage: Mache ich das heute oder nicht? Wer über Identität denkt, stellt die Frage gar nicht erst. Menschen, die sich als Nichtraucher sehen, sagen „Ich rauche nicht“ statt „Ich versuche aufzuhören“. Der erste Satz beschreibt, wer sie sind, der zweite einen Kampf, den sie täglich neu führen.\n\nDie Psychologie zeigt, dass wir gern im Einklang mit dem Bild handeln, das wir von uns selbst haben. In einer viel zitierten Studie reichte es, Menschen als „Wähler“ statt „wählen zu gehen“ anzusprechen, damit mehr von ihnen tatsächlich zur Wahl gingen. Wir wollen konsistent sein mit dem, der wir glauben zu sein.\n\nDer Haken: Du kannst dir eine neue Identität nicht einfach einreden. Wenn du dir sagst „Ich bin diszipliniert“ und dann drei Wochen nicht trainierst, glaubst du dir selbst nicht. Identität entsteht durch Beweise. Jede erledigte Einheit ist eine Stimme für den Menschen, der du werden willst. Du musst nicht jede Wahl gewinnen, du brauchst nur die Mehrheit.\n\nSo nutzt du das:\n\n**Formuliere, wer du sein willst, nicht was du erreichen willst.** Nicht „zehn Kilo mehr auf der Bank“, sondern „ich bin jemand, der seine Einheiten durchzieht“. Das Ergebnis folgt dem Verhalten, nicht umgekehrt.\n\n**Frag dich in schwierigen Momenten: Was würde diese Person jetzt tun?** Nicht „habe ich Lust?“, sondern „was macht jemand, der nicht verhandelt?“. Die Antwort ist meistens eindeutig.\n\n**Sammle Stimmen.** Jede Einheit, jeder abgehakte Tag, jede Mental-Aufgabe ist ein Beweis. Genau deshalb zählt unbroken Streaks und genau deshalb existiert das Cookie Jar: als Beweislage für deine neue Identität.\n\n**Sei geduldig.** Eine Identität wächst über Wochen und Monate. Am Anfang fühlt es sich wie Schauspielerei an. Irgendwann denkst du nicht mehr darüber nach.\n\nUnd wenn du ausrutschst: Eine verlorene Stimme ändert nichts an der Mehrheit. Wer eine Einheit verpasst, ist nicht plötzlich jemand, der nicht trainiert. Er ist jemand, der trainiert und einmal ausgefallen ist. Der Unterschied liegt darin, was er morgen macht.\n\n**Heute:** Schreib einen Satz auf, der mit „Ich bin jemand, der …“ beginnt. Und mach dann heute eine Sache, die diesen Satz wahr macht."},{"id":"M15","tier":2,"titel":"Erholung ist Training","untertitel":"Warum Muskeln in der Pause wachsen","reihenfolge":15,"umfrage_bezug":"Sicherheit","freischalt_trigger":"stagnation","woerter":362,"lesezeit_min":2,"datei":"texte/15_m15_erholung_ist_training.md","text":"In der Grind-Welt gilt Ruhe schnell als Schwäche. Wer sich ausruht, ist nicht hungrig genug. Das klingt hart und ist beim Muskelaufbau schlicht falsch.\n\nWas beim Training wirklich passiert: Im Gym setzt du einen Reiz. Du belastest deine Muskeln so, dass dein Körper das Signal bekommt, stärker werden zu müssen. Der eigentliche Aufbau passiert danach, in den Stunden und Tagen der Erholung. Ohne Erholung bleibt es beim Reiz und der Fortschritt bleibt aus. Training ist die Bestellung, Erholung die Lieferung.\n\n**Schlaf.** Der wichtigste und meistunterschätzte Faktor. Schlafmediziner empfehlen Jugendlichen bis 18 acht bis zehn Stunden pro Nacht, Erwachsenen sieben bis neun. Zu wenig Schlaf verschlechtert Leistung, Konzentration und Stimmung und macht es deutlich schwerer, Impulsen zu widerstehen. Wer um zwei Uhr nachts zockt und um sechs aufsteht, sabotiert seinen eigenen Plan.\n\n**Ruhetage.** Die Ruhetage in deinem Plan sind kein Lückenfüller. Sie sind so gesetzt, dass jede Muskelgruppe sich erholen kann, bevor sie wieder dran ist. Wer sie mit Extra-Einheiten füllt, trainiert nicht mehr, er erholt sich weniger.\n\n**Deload-Wochen.** Alle paar Wochen kommt eine Woche mit deutlich weniger Sätzen. Viele finden das frustrierend. Aber in diesen Wochen erholen sich Gelenke, Sehnen und Nervensystem, die langsamer mitwachsen als Muskeln. Danach bist du oft stärker als vorher.\n\nWoran du merkst, dass Erholung fehlt: Deine Leistung sinkt über mehrere Einheiten, obwohl du alles gibst. Du bist dauerhaft müde, gereizt oder unmotiviert. Du schläfst schlecht, obwohl du erschöpft bist. Gelenke zwicken häufiger. Wenn mehrere Übungen gleichzeitig stagnieren, liegt es selten am Plan, sondern meistens an Schlaf, Essen oder Stress. unbroken erkennt Leistungseinbrüche automatisch und nimmt dann Volumen raus. Den Rest musst du selbst machen.\n\nKonkret: feste Schlafenszeit, auch am Wochenende ungefähr gleich. Handy eine halbe Stunde vor dem Schlafen weglegen. Genug essen, um dein Training zu unterstützen, denn wer ständig unterversorgt trainiert, baut schlecht auf. Ruhetage locker gestalten: spazieren, dehnen, Rad fahren.\n\nDie unbequeme Wahrheit für alle, die nur auf Härte setzen: Wer sich nicht erholt, wird nicht härter. Er wird schwächer und irgendwann verletzt. Disziplin heißt auch, ins Bett zu gehen, wenn es Zeit ist.\n\n**Heute:** Leg eine feste Uhrzeit fest, ab der dein Handy nicht mehr im Bett liegt, und halte sie eine Woche durch."}]}$cd$::jsonb),
  ('regeln', 1, $cd${"tier":3,"auswertungsreihenfolge":"Nach 'prioritaet' aufsteigend. Niedrigere Zahl gewinnt. Eine Übung, die in dieser Woche bereits von einer Regel mit höherer Priorität verändert wurde, wird von Progressionsregeln (R10–R14) nicht mehr angefasst.","regeln":[{"id":"R01","name":"Schmerz gemeldet","kategorie":"sicherheit","prioritaet":1,"ausloeser":"feedback_uebung","bedingung_text":"Nutzer meldet bei einer Übung „Schmerz“ (Gelenk, stechend) und wählt eine Körperstelle.","bedingung":{"alle":[{"metrik":"uebung.feedback","op":"==","wert":"schmerz"}]},"aktion_text":"Übung sofort gegen die nächste Alternative aus dem Rotationspool desselben Slots tauschen. Für diesen Slot 14 Tage keine Progression. Hinweis anzeigen. Bei zweiter Meldung derselben Körperstelle innerhalb von 14 Tagen: Slot pausieren und deutlicher Hinweis auf Arzt/Physio.","aktion":{"typ":"uebung_tauschen","progression_sperren_tage":14,"eskalation_bei_wiederholung":true},"textbausteine":[],"mental_modul":"M13","user_bestaetigung":false,"cooldown_tage":0,"begruendung":"Schmerz in Gelenken ist ein Warnsignal, kein Trainingsreiz. Ausweichen statt durchziehen erhält die Trainierbarkeit.","nachricht":{"standard":"Wir tauschen die Übung aus und steigern hier erstmal nicht weiter. Wenn der Schmerz länger als eine Woche bleibt, nachts auftritt oder etwas anschwillt: bitte ärztlich abklären lassen.","knallhart":"Wir tauschen die Übung aus und steigern hier erstmal nicht weiter. Wenn der Schmerz länger als eine Woche bleibt, nachts auftritt oder etwas anschwillt: bitte ärztlich abklären lassen."}},{"id":"R02","name":"Pause 5–13 Tage / 3 verpasste Einheiten","kategorie":"comeback","prioritaet":2,"ausloeser":"plan_geladen","bedingung_text":"3 geplante Einheiten in Folge verpasst ODER 5 bis 13 Tage keine Einheit.","bedingung":{"eines":[{"metrik":"einheiten_verpasst_in_folge","op":">=","wert":3},{"metrik":"tage_seit_letzter_einheit","op":"zwischen","wert":[5,13]}]},"aktion_text":"Nächste 7 Tage: Satzzahl × 0,8 (abrunden, mindestens 2 bei main/sec), Gewichte unverändert, keine Progression in dieser Woche.","aktion":{"typ":"volumen_anpassen","saetze_faktor":0.8,"dauer_tage":7,"progression":false},"textbausteine":["CB02"],"mental_modul":null,"user_bestaetigung":false,"cooldown_tage":7,"begruendung":"Nach so kurzer Pause ist kaum Kraft verloren. Das reduzierte Volumen dient dem Wiedereinstieg und weniger Muskelkater, nicht dem Muskelerhalt.","nachricht":null},{"id":"R03","name":"Pause 14–27 Tage","kategorie":"comeback","prioritaet":2,"ausloeser":"plan_geladen","bedingung_text":"14 bis 27 Tage keine Einheit.","bedingung":{"alle":[{"metrik":"tage_seit_letzter_einheit","op":"zwischen","wert":[14,27]}]},"aktion_text":"Comeback-Woche: 1 Satz weniger pro Übung, Gewichte −10 % (Körpergewicht: eine Stufe zurück), Ziel-RIR 3. Danach normaler Blockverlauf.","aktion":{"typ":"comeback_woche","saetze_delta":-1,"gewicht_faktor":0.9,"stufe_delta":-1,"rir":"3","dauer_tage":7},"textbausteine":["CB04"],"mental_modul":null,"user_bestaetigung":false,"cooldown_tage":14,"begruendung":"Nach zwei bis vier Wochen Pause sinkt vor allem die Belastungstoleranz, weniger die Muskelmasse. Reduzierter Wiedereinstieg senkt Verletzungs- und Abbruchrisiko.","nachricht":null},{"id":"R04","name":"Pause ab 28 Tagen","kategorie":"comeback","prioritaet":2,"ausloeser":"plan_geladen","bedingung_text":"28 Tage oder länger keine Einheit.","bedingung":{"alle":[{"metrik":"tage_seit_letzter_einheit","op":">=","wert":28}]},"aktion_text":"Block auf Woche 1 zurücksetzen, Gewichte −20 % bzw. eine Stufe zurück, Onboarding-Check anbieten („Hat sich etwas an Zeit, Ausstattung oder Zielen geändert?“).","aktion":{"typ":"neustart","block_woche":1,"gewicht_faktor":0.8,"stufe_delta":-1,"onboarding_check":true},"textbausteine":["CB05"],"mental_modul":"M09","user_bestaetigung":false,"cooldown_tage":0,"begruendung":"Nach über einem Monat ist ein sauberer Wiedereinstieg sinnvoller als das alte Pensum. Muskelgedächtnis bringt die Leistung schnell zurück.","nachricht":null},{"id":"R05","name":"Erste Einheit nach Pause erledigt","kategorie":"motivation","prioritaet":9,"ausloeser":"einheit_abgeschlossen","bedingung_text":"Letzte Pause war ≥ 5 Tage und die erste Einheit danach ist abgeschlossen.","bedingung":{"alle":[{"metrik":"letzte_pause_tage","op":">=","wert":5}]},"aktion_text":"Textbaustein anzeigen.","aktion":{"typ":"nur_text"},"textbausteine":["CB06"],"mental_modul":null,"user_bestaetigung":false,"cooldown_tage":5,"begruendung":"","nachricht":null},{"id":"R06","name":"Deload fällig","kategorie":"planstruktur","prioritaet":3,"ausloeser":"woche_beginnt","bedingung_text":"Aktuelle Blockwoche ist die Deload-Woche (Anfänger Woche 8, Fortgeschritten Woche 5).","bedingung":{"alle":[{"metrik":"block_woche","op":"==","wert":"deload_woche"}]},"aktion_text":"Satzzahl × 0,5 (aufrunden, min. 1), gleiche Gewichte, Ziel-RIR 4, keine Progression in dieser Woche.","aktion":{"typ":"deload","saetze_faktor":0.5,"rir":"4","progression":false},"textbausteine":["SG06"],"mental_modul":null,"user_bestaetigung":false,"cooldown_tage":0,"begruendung":"Geplante Entlastung gibt Gelenken, Sehnen und Nervensystem Zeit, nachzuziehen. Muskelmasse geht in einer Woche mit halbem Volumen nicht verloren.","nachricht":null},{"id":"R07","name":"Leistungseinbruch","kategorie":"erholung","prioritaet":4,"ausloeser":"einheit_abgeschlossen","bedingung_text":"Bei gleichem Gewicht fallen die Wiederholungen einer Übung in 2 Einheiten in Folge um ≥ 20 % ODER mindestens 2 Übungen einer Einheit brechen gleichzeitig ein.","bedingung":{"eines":[{"metrik":"uebung.wdh_einbruch_prozent_in_folge","op":">=","wert":20},{"metrik":"einheit.uebungen_mit_einbruch","op":">=","wert":2}]},"aktion_text":"Nächste 3 Einheiten: 1 Satz weniger pro Übung, keine Progression. Hinweis auf Schlaf und Essen.","aktion":{"typ":"volumen_anpassen","saetze_delta":-1,"dauer_einheiten":3,"progression":false},"textbausteine":["SG03"],"mental_modul":"M15","user_bestaetigung":false,"cooldown_tage":10,"begruendung":"Sinkende Leistung bei gleichem Gewicht ist meist ein Erholungsproblem, kein Motivationsproblem. Volumen senken statt Willen erhöhen.","nachricht":null},{"id":"R08","name":"Stagnation: mehrere Übungen","kategorie":"stagnation","prioritaet":5,"ausloeser":"woche_endet","bedingung_text":"In derselben Woche stagnieren 3 oder mehr Übungen (keine Steigerung in Wiederholungen oder Gewicht seit 3 Einheiten).","bedingung":{"alle":[{"metrik":"anzahl_uebungen_stagnierend","op":">=","wert":3}]},"aktion_text":"Keine Übungswechsel. Stattdessen Hinweis auf Schlaf/Ernährung/Stress und Modul 15 freischalten. Regel R09 in dieser Woche unterdrücken.","aktion":{"typ":"nur_text","unterdrueckt":["R09"]},"textbausteine":["SG02"],"mental_modul":"M15","user_bestaetigung":false,"cooldown_tage":14,"begruendung":"Wenn alles gleichzeitig steht, liegt es fast nie an der Übungsauswahl.","nachricht":null},{"id":"R09","name":"Stagnation: einzelne Übung","kategorie":"stagnation","prioritaet":5,"ausloeser":"einheit_abgeschlossen","bedingung_text":"Eine Übung wurde 3 Einheiten in Folge nicht gesteigert (weder Wiederholungen noch Gewicht/Stufe).","bedingung":{"alle":[{"metrik":"uebung.einheiten_ohne_steigerung","op":">=","wert":3}]},"aktion_text":"Vorschlag: Übung gegen die nächste Alternative aus dem Rotationspool des Slots tauschen (mit Bestätigung). Bei Körpergewichtsübungen stattdessen Zwischenstufe: 2 Sek Pause im schwersten Punkt.","aktion":{"typ":"uebung_rotieren","quelle":"slots.json → rotation","bodyweight_alternative":"pause_2_sek"},"textbausteine":["SG01","SG05"],"mental_modul":null,"user_bestaetigung":true,"cooldown_tage":14,"begruendung":"Ein neuer Reiz durch Variation ist wirksamer als ewig dieselbe stehende Übung.","nachricht":null},{"id":"R10","name":"Doppelte Progression (Gewicht)","kategorie":"progression","prioritaet":6,"ausloeser":"einheit_abgeschlossen","bedingung_text":"Alle Sätze einer Übung haben das obere Ende der Wiederholungsspanne erreicht (Profil Gym oder Home-Gym, schwerste Hantel noch nicht erreicht).","bedingung":{"alle":[{"metrik":"uebung.alle_saetze_oberes_ende","op":"==","wert":true},{"metrik":"profil","op":"in","wert":["gym","homegym"]},{"metrik":"uebung.ist_max_gewicht","op":"==","wert":false}]},"aktion_text":"Nächste Einheit: Gewicht erhöhen (Unterkörper-Grundübung +2,5–5 kg, Oberkörper +1–2,5 kg, Isolation kleinste verfügbare Stufe), Wiederholungen zurück auf das untere Ende der Spanne.","aktion":{"typ":"gewicht_erhoehen","unterkoerper_kg":[2.5,5],"oberkoerper_kg":[1,2.5],"wdh_reset":"unteres_ende"},"textbausteine":[],"mental_modul":null,"user_bestaetigung":false,"cooldown_tage":0,"begruendung":"Leistungsbasierte Progression statt fester Zeitformel: Die Last steigt erst, wenn die Leistung es zeigt.","nachricht":null},{"id":"R11","name":"Stufen-Progression (Körpergewicht)","kategorie":"progression","prioritaet":6,"ausloeser":"einheit_abgeschlossen","bedingung_text":"Alle Sätze einer Stufen-Übung haben das obere Ende der Wiederholungsspanne erreicht und es gibt eine höhere Stufe.","bedingung":{"alle":[{"metrik":"uebung.alle_saetze_oberes_ende","op":"==","wert":true},{"metrik":"uebung.hat_naechste_stufe","op":"==","wert":true}]},"aktion_text":"Nächste Einheit: eine Stufe höher, Wiederholungen zurück auf das untere Ende.","aktion":{"typ":"stufe_erhoehen","wdh_reset":"unteres_ende"},"textbausteine":[],"mental_modul":null,"user_bestaetigung":false,"cooldown_tage":0,"begruendung":"Ohne Gewichte läuft Progression über schwerere Varianten (Hebel, Einbeinigkeit, Bewegungsweg).","nachricht":null},{"id":"R12","name":"Kein Gewicht / keine Stufe mehr übrig","kategorie":"progression","prioritaet":6,"ausloeser":"einheit_abgeschlossen","bedingung_text":"Obere Wiederholungsgrenze erreicht UND schwerste Hantel bzw. letzte Stufe erreicht.","bedingung":{"alle":[{"metrik":"uebung.alle_saetze_oberes_ende","op":"==","wert":true},{"eines":[{"metrik":"uebung.ist_max_gewicht","op":"==","wert":true},{"metrik":"uebung.hat_naechste_stufe","op":"==","wert":false}]}]},"aktion_text":"Intensitätstechnik in dieser Reihenfolge freischalten: 1) Tempo 3-1-1, 2) zusätzlich 2 Sek Pause im schwersten Punkt, 3) Wiederholungsspanne um 5 erhöhen (Obergrenze 30).","aktion":{"typ":"intensitaetstechnik","stufen":["tempo_3_1_1","pause_2_sek","wdh_spanne_plus_5"],"wdh_max":30},"textbausteine":["SG04"],"mental_modul":null,"user_bestaetigung":false,"cooldown_tage":0,"begruendung":"Wiederholungsbereiche von etwa 5 bis 30 wirken ähnlich gut für Muskelaufbau, solange nah am Muskelversagen trainiert wird.","nachricht":null},{"id":"R13","name":"Einstufung bei Körpergewichtsübung","kategorie":"progression","prioritaet":6,"ausloeser":"einheit_abgeschlossen","bedingung_text":"Erste Einheit mit einer Stufen-Übung: erster Satz liegt unter dem unteren Ende (zu schwer) oder mehr als 5 Wiederholungen über dem oberen Ende (zu leicht).","bedingung":{"eines":[{"metrik":"uebung.erste_einheit_wdh","op":"<","wert":"unteres_ende"},{"metrik":"uebung.erste_einheit_wdh","op":">","wert":"oberes_ende_plus_5"}]},"aktion_text":"Stufe automatisch um 1 nach unten bzw. oben korrigieren und Nutzer kurz informieren.","aktion":{"typ":"stufe_korrigieren","delta":[-1,1]},"textbausteine":[],"mental_modul":null,"user_bestaetigung":false,"cooldown_tage":0,"begruendung":"Die richtige Startstufe entscheidet, ob Körpergewichtstraining überhaupt im wirksamen Bereich landet.","nachricht":null},{"id":"R14","name":"Feedback „zu leicht“","kategorie":"progression","prioritaet":6,"ausloeser":"feedback_uebung","bedingung_text":"Nutzer meldet bei derselben Übung 2 Einheiten in Folge „zu leicht“ (geschätzte RIR ≥ 4).","bedingung":{"alle":[{"metrik":"uebung.feedback_zu_leicht_in_folge","op":">=","wert":2}]},"aktion_text":"Nächste Einheit: Gewicht eine Stufe hoch bzw. Stufe +1, auch wenn das obere Wiederholungsende noch nicht erreicht ist.","aktion":{"typ":"gewicht_erhoehen","erzwungen":true},"textbausteine":[],"mental_modul":null,"user_bestaetigung":false,"cooldown_tage":0,"begruendung":"Zu weit vom Muskelversagen entfernt zu trainieren kostet Wachstumsreiz.","nachricht":null},{"id":"R15","name":"Feedback „zu schwer“","kategorie":"sicherheit","prioritaet":4,"ausloeser":"feedback_uebung","bedingung_text":"Nutzer meldet bei derselben Übung 2 Einheiten in Folge „zu schwer“ oder schafft das untere Wiederholungsende nicht.","bedingung":{"alle":[{"metrik":"uebung.feedback_zu_schwer_in_folge","op":">=","wert":2}]},"aktion_text":"Gewicht −5 bis −10 % bzw. eine Stufe zurück, Technik-Hinweis einblenden.","aktion":{"typ":"gewicht_senken","faktor":0.925,"stufe_delta":-1},"textbausteine":["DH05"],"mental_modul":null,"user_bestaetigung":false,"cooldown_tage":0,"begruendung":"Zu schwere Lasten verschlechtern Technik und erhöhen das Verletzungsrisiko, ohne mehr Wachstum zu bringen.","nachricht":null},{"id":"R16","name":"Wochentag wird regelmäßig verpasst","kategorie":"planstruktur","prioritaet":8,"ausloeser":"woche_endet","bedingung_text":"Derselbe Wochentag wurde in 3 der letzten 4 Wochen verpasst.","bedingung":{"alle":[{"metrik":"wochentag_verpasst_anzahl_4wochen","op":">=","wert":3}]},"aktion_text":"Vorschlag: diesen Wochentag dauerhaft zum Ruhetag machen und die Einheit auf einen anderen Tag legen. Reihenfolge der Tagesprofile bleibt gleich.","aktion":{"typ":"wochenmuster_anpassen","bestaetigung_noetig":true},"textbausteine":[],"mental_modul":null,"user_bestaetigung":true,"cooldown_tage":28,"begruendung":"Ein Plan, der zum echten Wochenablauf passt, wird eher eingehalten als einer, der gegen ihn arbeitet.","nachricht":{"standard":"Dienstags klappt es bei dir selten. Sollen wir den Tag fest zum Ruhetag machen und die Einheit verschieben?","knallhart":"Dienstag verlierst du regelmäßig. Entweder du gewinnst ihn zurück oder wir machen ihn offiziell zum Ruhetag. Deine Wahl."}},{"id":"R17","name":"Zeitbudget zu knapp","kategorie":"planstruktur","prioritaet":7,"ausloeser":"plan_erstellt","bedingung_text":"Geschätzte Dauer einer Einheit überschreitet das im Profil hinterlegte Zeitbudget.","bedingung":{"alle":[{"metrik":"einheit.dauer_geschaetzt_min","op":">","wert":"profil.zeitbudget_min"}]},"aktion_text":"1) Antagonisten-Supersätze bilden (Drücken + Ziehen, Quadrizeps + Beinbeuger), 2) falls immer noch zu lang: Übungen mit Rolle „acc“ von hinten streichen, Rumpfübung zuletzt. Übungen mit Rolle „main“ und „sec“ bleiben immer erhalten.","aktion":{"typ":"einheit_kuerzen","reihenfolge":["supersaetze","acc_streichen","core_streichen"],"nie_streichen":["main","sec"]},"textbausteine":[],"mental_modul":null,"user_bestaetigung":false,"cooldown_tage":0,"begruendung":"Grundübungen liefern den größten Teil des Reizes. Lieber kurz und vollständig als lang und ausgelassen.","nachricht":null},{"id":"R18","name":"Streak-Meilenstein","kategorie":"motivation","prioritaet":9,"ausloeser":"tag_abgeschlossen","bedingung_text":"Streak erreicht 3, 7, 14, 30, 40, 66 oder 100 Tage.","bedingung":{"alle":[{"metrik":"streak_tage","op":"in","wert":[3,7,14,30,40,66,100]}]},"aktion_text":"Passenden Meilenstein-Textbaustein anzeigen, Eintrag automatisch fürs Cookie Jar vorschlagen.","aktion":{"typ":"meilenstein","cookie_jar_vorschlag":true},"textbausteine":["ST01","ST02","ST03","ST04","ST05","ST06","ST07"],"mental_modul":null,"user_bestaetigung":false,"cooldown_tage":0,"begruendung":"Sichtbare Erfolge stärken die Selbstwirksamkeit – die stärkste Quelle für Durchhaltevermögen.","nachricht":null},{"id":"R19","name":"14er-Streak: Steigerung prüfen","kategorie":"progression","prioritaet":6,"ausloeser":"tag_abgeschlossen","bedingung_text":"Streak = 14 Tage UND mindestens die Hälfte der Übungen wurde in den letzten 14 Tagen gesteigert UND keine Schmerzmeldung in diesem Zeitraum.","bedingung":{"alle":[{"metrik":"streak_tage","op":"==","wert":14},{"metrik":"anteil_uebungen_mit_progression_14t","op":">=","wert":0.5},{"metrik":"schmerzmeldungen_14t","op":"==","wert":0}]},"aktion_text":"Angebot (mit Bestätigung): +1 Satz bei der ersten Übung jeder Einheit für den Rest des Blocks, oder – nach mindestens einem abgeschlossenen Block – Wechsel auf Level „Fortgeschritten“.","aktion":{"typ":"steigerung_anbieten","optionen":["saetze_plus_1_main","level_upgrade"]},"textbausteine":[],"mental_modul":null,"user_bestaetigung":true,"cooldown_tage":0,"begruendung":"Eine Streak zeigt Konsistenz, nicht Belastbarkeit. Mehr Volumen nur, wenn auch die Leistungsdaten mitziehen.","nachricht":null},{"id":"R20","name":"Mental-Aufgabe mehrfach offen","kategorie":"motivation","prioritaet":9,"ausloeser":"tag_abgeschlossen","bedingung_text":"Mental-Aufgabe an 3 Tagen in Folge nicht erledigt (nur wenn Mental-Modul aktiviert ist).","bedingung":{"alle":[{"metrik":"mental_offen_in_folge","op":">=","wert":3}]},"aktion_text":"Textbaustein anzeigen und für den nächsten Tag die Mini-Version der Aufgabe vorschlagen (max. 5 Minuten).","aktion":{"typ":"aufgabe_verkleinern","dauer_max_min":5},"textbausteine":["DH02"],"mental_modul":null,"user_bestaetigung":false,"cooldown_tage":7,"begruendung":"","nachricht":null},{"id":"R21","name":"Woche unter 50 Prozent","kategorie":"motivation","prioritaet":9,"ausloeser":"woche_endet","bedingung_text":"Weniger als die Hälfte der geplanten Einheiten der Woche erledigt.","bedingung":{"alle":[{"metrik":"woche.erledigt_anteil","op":"<","wert":0.5}]},"aktion_text":"Wochenabschluss-Text anzeigen, zum Wochenstart Neustart-Text.","aktion":{"typ":"nur_text"},"textbausteine":["DH03","DH07"],"mental_modul":"M04","user_bestaetigung":false,"cooldown_tage":7,"begruendung":"","nachricht":null},{"id":"R22","name":"Wochenmitte, Woche hängt","kategorie":"motivation","prioritaet":9,"ausloeser":"tag_beginnt","bedingung_text":"Mitte der Woche (Tag 4 des Wochenmusters) und mindestens 2 Einheiten der Woche noch offen.","bedingung":{"alle":[{"metrik":"woche.tag_index","op":"==","wert":4},{"metrik":"woche.offene_einheiten","op":">=","wert":2}]},"aktion_text":"Textbaustein anzeigen.","aktion":{"typ":"nur_text"},"textbausteine":["DH01"],"mental_modul":null,"user_bestaetigung":false,"cooldown_tage":7,"begruendung":"","nachricht":null},{"id":"R23","name":"App länger nicht geöffnet","kategorie":"motivation","prioritaet":9,"ausloeser":"taeglich","bedingung_text":"App seit 5 Tagen nicht geöffnet (nur wenn Benachrichtigungen erlaubt sind).","bedingung":{"alle":[{"metrik":"app_nicht_geoeffnet_tage","op":">=","wert":5}]},"aktion_text":"Eine Erinnerung senden, danach 14 Tage Ruhe.","aktion":{"typ":"nur_text"},"textbausteine":["DH04"],"mental_modul":null,"user_bestaetigung":false,"cooldown_tage":14,"begruendung":"","nachricht":null},{"id":"R24","name":"Einheit unvollständig","kategorie":"motivation","prioritaet":9,"ausloeser":"einheit_abgeschlossen","bedingung_text":"Weniger als die Hälfte der geplanten Sätze geloggt, Einheit aber beendet.","bedingung":{"alle":[{"metrik":"einheit.saetze_anteil","op":"<","wert":0.5}]},"aktion_text":"Einheit zählt als erledigt (Streak bleibt), für die nicht geloggten Übungen greift keine Progression.","aktion":{"typ":"teilweise_werten","progression_nur_geloggte":true},"textbausteine":["DH06"],"mental_modul":null,"user_bestaetigung":false,"cooldown_tage":0,"begruendung":"","nachricht":null},{"id":"R25","name":"Keine Gewichte geloggt","kategorie":"system","prioritaet":8,"ausloeser":"woche_endet","bedingung_text":"Seit 14 Tagen wurden keine Gewichte oder Wiederholungen eingetragen.","bedingung":{"alle":[{"metrik":"tage_ohne_leistungslog","op":">=","wert":14}]},"aktion_text":"Hinweis anzeigen: Ohne Logs kann die automatische Progression nicht greifen.","aktion":{"typ":"nur_text"},"textbausteine":[],"mental_modul":null,"user_bestaetigung":false,"cooldown_tage":21,"begruendung":"","nachricht":{"standard":"Du hakst ab, trägst aber keine Gewichte ein. Ohne diese Zahlen kann dein Plan nicht automatisch steigern – zwei Sekunden pro Satz reichen.","knallhart":"Abhaken allein bringt dich nicht weiter. Ohne Zahlen keine Progression. Trag die Sätze ein."}},{"id":"R26","name":"Challenge: Tag verpasst","kategorie":"challenge","prioritaet":2,"ausloeser":"tag_endet","bedingung_text":"40-Tage-Challenge läuft und der freigeschaltete Tag wurde bis Ende des Kalendertags nicht abgeschlossen.","bedingung":{"alle":[{"metrik":"challenge.aktiv","op":"==","wert":true},{"metrik":"challenge.tag_offen_am_tagesende","op":"==","wert":true}]},"aktion_text":"Soft-Modus (Standard): Streak zurück auf 0, der Tag bleibt offen und wird nachgeholt. Hardcore-Modus (nur wenn vorher aktiviert): Challenge startet wieder bei Tag 1.","aktion":{"typ":"challenge_verpasst","soft":{"streak":0,"tag_bleibt_offen":true},"hardcore":{"reset_auf_tag":1}},"textbausteine":["CB01","CB07"],"mental_modul":"M04","user_bestaetigung":false,"cooldown_tage":0,"begruendung":"Harte Resets erzeugen den Alles-oder-nichts-Effekt und damit Abbrüche. Deshalb ist der weiche Modus Standard und Härte eine freiwillige Entscheidung.","nachricht":null},{"id":"R27","name":"Challenge abgeschlossen","kategorie":"challenge","prioritaet":3,"ausloeser":"tag_abgeschlossen","bedingung_text":"Tag 40 der Challenge abgeschlossen.","bedingung":{"alle":[{"metrik":"challenge.tag","op":"==","wert":40}]},"aktion_text":"Abzeichen „40 Days Unbroken“ vergeben, Cookie-Jar-Eintrag vorschlagen, Übergang in den regulären 4-Tage-Plan anbieten (Gewichte und Stufen werden übernommen), Level und Trainingstage neu abfragen.","aktion":{"typ":"challenge_abschluss","badge":"40_days_unbroken","uebergang":"4tage_plan"},"textbausteine":["ST05"],"mental_modul":null,"user_bestaetigung":false,"cooldown_tage":0,"begruendung":"","nachricht":null},{"id":"R28","name":"Wochenauswertung","kategorie":"system","prioritaet":9,"ausloeser":"woche_endet","bedingung_text":"Jede Woche zum Wochenende, sobald mindestens eine Woche Daten vorliegt.","bedingung":{"alle":[{"metrik":"woche.abgeschlossen","op":"==","wert":true}]},"aktion_text":"Wochenbericht bauen: Kennzahlen + genau ein Textbaustein nach Priorität (Sicherheit > Comeback > Stagnation > Durchhänger > Meilenstein).","aktion":{"typ":"wochenbericht","vorlage":"wochenauswertung","max_textbausteine":1},"textbausteine":["SG07"],"mental_modul":null,"user_bestaetigung":false,"cooldown_tage":0,"begruendung":"Ein Feedback pro Woche wird gelesen. Fünf Hinweise gleichzeitig werden ignoriert.","nachricht":null}]}$cd$::jsonb),
  ('textbausteine', 1, $cd${"tier":3,"bausteine":[{"id":"DH01","kategorie":"durchhaenger","anlass":"Wochenmitte, mehrere Einheiten offen","standard":"Die Woche ist noch nicht gelaufen. {offene_einheiten} Einheiten offen – eine davon heute, und du bist wieder im Plan.","knallhart":"{offene_einheiten} Einheiten offen. Die Woche entscheidet sich nicht am Sonntag, sondern heute.","platzhalter":["offene_einheiten"]},{"id":"DH02","kategorie":"durchhaenger","anlass":"Mental-Aufgabe 3 Tage offen","standard":"Drei Tage ohne Mental-Aufgabe. Kein Drama – nimm heute die kleinste Version, fünf Minuten reichen.","knallhart":"Drei Tage nichts abgehakt. Du musst nicht groß anfangen. Nur anfangen. Fünf Minuten, jetzt.","platzhalter":[]},{"id":"DH03","kategorie":"durchhaenger","anlass":"Woche unter 50 Prozent (Wochenende)","standard":"Diese Woche lief nur die Hälfte. Schau kurz hin, was dazwischenkam – und leg für die nächste Einheit eine feste Uhrzeit fest.","knallhart":"Halbe Woche, halbe Ergebnisse. Uhrzeit für die nächste Einheit festlegen. Nicht „irgendwann“.","platzhalter":[]},{"id":"DH04","kategorie":"durchhaenger","anlass":"App 5 Tage nicht geöffnet","standard":"Lange nichts von dir gehört. Dein Plan ist noch da, genau an der Stelle, an der du aufgehört hast.","knallhart":"Fünf Tage weg. Der Plan hat gewartet. Die Frage ist, worauf du wartest.","platzhalter":[]},{"id":"DH05","kategorie":"durchhaenger","anlass":"Mehrfach „zu schwer“ gemeldet","standard":"Wenn sich gerade alles schwer anfühlt, ist das eine Information, kein Urteil. Wir nehmen Gewicht raus und bauen wieder auf.","knallhart":"Schwere Phase. Passiert jedem, der ernsthaft trainiert. Gewicht runter, Standards bleiben.","platzhalter":[]},{"id":"DH06","kategorie":"durchhaenger","anlass":"Einheit unvollständig","standard":"Nicht alles geschafft heute – aber du warst da. Eine halbe Einheit schlägt null Einheiten jedes Mal.","knallhart":"Halb durchgezogen ist trotzdem erschienen. Nächstes Mal bis zum letzten Satz.","platzhalter":[]},{"id":"DH07","kategorie":"durchhaenger","anlass":"Neue Woche nach schwacher Woche","standard":"Neue Woche, sauberer Start. Du musst die letzte nicht aufholen – nur die nächste Einheit machen.","knallhart":"Letzte Woche ist gelaufen. Nicht nachtrauern, nicht nachholen. Erste Einheit. Heute.","platzhalter":[]},{"id":"ST01","kategorie":"streak_meilenstein","anlass":"3 Tage Streak","standard":"Drei Tage am Stück. Der schwerste Teil – anfangen – liegt hinter dir.","knallhart":"Drei Tage. Das schaffen viele. Mal sehen, ob du zu den wenigen gehörst, die bei 30 noch da sind.","platzhalter":["streak"]},{"id":"ST02","kategorie":"streak_meilenstein","anlass":"7 Tage Streak","standard":"Eine volle Woche nach Plan. Das ist die erste Woche, die wirklich zählt.","knallhart":"Sieben Tage ohne Ausrede. Mach daraus zwei Wochen.","platzhalter":["streak"]},{"id":"ST03","kategorie":"streak_meilenstein","anlass":"14 Tage Streak","standard":"14 Tage. Du baust gerade etwas auf, das nicht mehr von Motivation abhängt.","knallhart":"14 Tage. Ab hier hören die meisten auf, weil der Reiz des Neuen weg ist. Du nicht.","platzhalter":["streak"]},{"id":"ST04","kategorie":"streak_meilenstein","anlass":"30 Tage Streak","standard":"30 Tage. Ein Monat, in dem du dich auf dich selbst verlassen konntest.","knallhart":"30 Tage. Das ist kein Zufall mehr. Das bist du.","platzhalter":["streak"]},{"id":"ST05","kategorie":"streak_meilenstein","anlass":"40 Tage Streak / Challenge geschafft","standard":"40 Tage. Du hast bewiesen, dass du durchziehen kannst – schreib das in dein Cookie Jar.","knallhart":"40 Tage unbroken. Merk dir dieses Gefühl. Du wirst es brauchen, wenn es wieder hart wird.","platzhalter":["streak"]},{"id":"ST06","kategorie":"streak_meilenstein","anlass":"66 Tage Streak","standard":"66 Tage. In einer bekannten Studie zur Gewohnheitsbildung war das im Schnitt die Zeit, bis Verhalten automatisch wird.","knallhart":"66 Tage. Statistisch ist das jetzt Gewohnheit. Das heißt nicht, dass es leicht wird. Es heißt, dass du nicht mehr verhandelst.","platzhalter":["streak"]},{"id":"ST07","kategorie":"streak_meilenstein","anlass":"100 Tage Streak","standard":"100 Tage. Dreistellig. Die meisten Menschen schaffen das bei keiner einzigen Sache.","knallhart":"100. Dreistellig. Du bist nicht mehr derselbe wie an Tag 1.","platzhalter":["streak"]},{"id":"CB01","kategorie":"comeback","anlass":"Ein Tag verpasst","standard":"Gestern ist ausgefallen. Heute zählt doppelt – nicht schwerer, sondern weil zweimal hintereinander der eigentliche Fehler wäre.","knallhart":"Einmal verpasst ist ein Ausrutscher. Zweimal ist ein Muster. Heute entscheidest du, welches von beiden.","platzhalter":[]},{"id":"CB02","kategorie":"comeback","anlass":"3 verpasste Einheiten / 5–13 Tage Pause","standard":"Willkommen zurück. Diese Woche läuft mit etwas weniger Volumen – nicht weil du Muskeln verloren hast (hast du nicht), sondern damit der Wiedereinstieg sitzt.","knallhart":"Zurück. Diese Woche 20 Prozent weniger Volumen. Kein Geschenk, ein Wiedereinstieg. Nächste Woche wieder voll.","platzhalter":["tage_pause"]},{"id":"CB03","kategorie":"comeback","anlass":"7–13 Tage Pause","standard":"Eine Woche Pause ist für deinen Körper fast nichts – Kraft und Muskeln sind noch da. Wir fahren nur kurz kontrolliert hoch.","knallhart":"Eine Woche weg. Dein Körper hat es kaum gemerkt. Dein Kopf schon. Zeig ihm, wer entscheidet.","platzhalter":["tage_pause"]},{"id":"CB04","kategorie":"comeback","anlass":"14–27 Tage Pause","standard":"Nach zwei bis vier Wochen Pause starten wir mit einer Comeback-Woche: etwas weniger Gewicht, ein Satz weniger. Dein Körper erinnert sich schneller, als du denkst.","knallhart":"Wochen weg, egal warum. Comeback-Woche: weniger Gewicht, gleiche Standards. Keine Diskussion über die Pause.","platzhalter":["tage_pause"]},{"id":"CB05","kategorie":"comeback","anlass":"Ab 28 Tagen Pause","standard":"Neustart. Kein Grund für ein schlechtes Gewissen – das Wichtigste ist, dass du wieder da bist. Wir setzen den Block zurück und prüfen kurz, ob dein Profil noch passt.","knallhart":"Über einen Monat weg. Neustart bei Woche 1. Die Vergangenheit ist egal, die nächsten sieben Tage nicht.","platzhalter":["tage_pause"]},{"id":"CB06","kategorie":"comeback","anlass":"Erste Einheit nach Pause erledigt","standard":"Erste Einheit nach der Pause: erledigt. Das war der schwerste Schritt.","knallhart":"Erste Einheit zurück. Der Kopf wollte nicht, du hast es trotzdem gemacht. Genau so.","platzhalter":[]},{"id":"CB07","kategorie":"comeback","anlass":"Challenge-Neustart nach Hardcore-Reset","standard":"Zurück auf Tag 1. Das tut weh – aber du weißt jetzt, wo es bei dir hakt. Das wissen die wenigsten beim ersten Versuch.","knallhart":"Tag 1. Wieder. Du hast den Hardcore-Modus gewählt, du kennst die Regeln. Diesmal weißt du, wo die Falle liegt.","platzhalter":[]},{"id":"SG01","kategorie":"stagnation","anlass":"Einzelne Übung stagniert","standard":"Bei {uebung} geht seit drei Einheiten nichts mehr voran. Völlig normal – Fortschritt ist keine gerade Linie. Wir setzen einen neuen Reiz mit einer Variante.","knallhart":"{uebung} steht. Drei Einheiten ohne Plus. Neue Variante, neuer Reiz. Kein Grund zur Panik, Grund zum Anpassen.","platzhalter":["uebung"]},{"id":"SG02","kategorie":"stagnation","anlass":"Mehrere Übungen stagnieren","standard":"Mehrere Übungen stehen gleichzeitig. Das liegt selten am Plan, meistens an Schlaf, Essen oder Stress. Ehrliche Frage: Schläfst du gerade genug?","knallhart":"Alles steht gleichzeitig? Dann ist nicht der Plan das Problem. Schlaf, Essen, Stress – ehrlich prüfen.","platzhalter":[]},{"id":"SG03","kategorie":"stagnation","anlass":"Leistungseinbruch","standard":"Deine Wiederholungen sind deutlich eingebrochen. Das ist meistens ein Erholungsthema. Die nächsten Einheiten laufen mit einem Satz weniger.","knallhart":"Leistung runter. Kein Charakterfehler, ein Erholungsproblem. Ein Satz weniger, mehr Schlaf, dann wieder angreifen.","platzhalter":["uebung"]},{"id":"SG04","kategorie":"stagnation","anlass":"Maximalgewicht / letzte Stufe erreicht","standard":"Bei {uebung} bist du am Ende dessen, was dein Equipment hergibt. Ab jetzt wird über Tempo gesteigert: drei Sekunden ablassen, kurz halten, kontrolliert hoch.","knallhart":"Zu leicht geworden? Gut. Jetzt Tempo: drei Sekunden runter. Das Gewicht bleibt gleich, die Anstrengung nicht.","platzhalter":["uebung"]},{"id":"SG05","kategorie":"stagnation","anlass":"Körpergewicht: Stufe festgefahren","standard":"Du hängst bei {uebung} auf Stufe {stufe} fest. Zwischenschritt: gleiche Übung, aber zwei Sekunden Pause im schwersten Punkt.","knallhart":"Festgefahren auf Stufe {stufe}. Zwei Sekunden Pause unten. Dann weiter.","platzhalter":["uebung","stufe"]},{"id":"SG06","kategorie":"stagnation","anlass":"Deload-Woche startet","standard":"Diese Woche ist Deload: weniger Sätze, gleiche Gewichte. Kein Rückschritt – das ist die Woche, in der dein Körper den Fortschritt der letzten Wochen einsammelt.","knallhart":"Deload. Weniger machen fällt manchen schwerer als mehr machen. Trotzdem durchziehen – Erholung ist Teil des Plans.","platzhalter":[]},{"id":"SG07","kategorie":"stagnation","anlass":"Gefühlte Stagnation, Zahlen steigen","standard":"Es fühlt sich an, als würde nichts passieren? Deine Zahlen sagen etwas anderes: {uebung} ist seit dem Start um {steigerung} gestiegen. Fortschritt ist leiser, als man denkt.","knallhart":"Du siehst keinen Fortschritt? Deine Zahlen schon: {uebung} plus {steigerung}. Gefühle lügen, Logbücher nicht.","platzhalter":["uebung","steigerung"]}],"vorlagen":{"wochenauswertung":{"standard":"**Woche {woche}**\n{erledigt}/{geplant} Einheiten · Streak {streak} Tage · {progressionen} Übungen gesteigert\n\n{textbaustein}","knallhart":"**WOCHE {woche}**\n{erledigt}/{geplant} Einheiten · Streak {streak} · {progressionen} Übungen gesteigert\n\n{textbaustein}"},"hinweis":"Pro Wochenbericht wird genau ein Textbaustein eingesetzt. Reihenfolge der Priorität: Sicherheit > Comeback > Stagnation > Durchhänger > Meilenstein."},"hinweis":"Platzhalter in geschweiften Klammern werden zur Laufzeit ersetzt. Der Ton (standard/knallhart) kommt aus den Einstellungen."}$cd$::jsonb),
  ('ton_varianten', 1, $cd${"hinweis":"Der Ton wird in den Einstellungen gewählt und ändert ausschließlich Texte, niemals Übungen, Sätze, Wiederholungen oder Regeln. Sicherheitshinweise sind in beiden Tönen identisch.","texte":{"plan_intro":{"standard":"Das ist dein Plan. Er wächst mit dir. Auftauchen, ausführen, der Rest kommt von selbst.","knallhart":"Der Plan steht. Niemand macht ihn für dich. Du entscheidest jeden Tag neu, ob du ihn benutzt oder dir eine Ausrede suchst."},"satz_anweisung":{"standard":"{saetze} Sätze, {wdh} Wiederholungen. Sauber ausführen – lieber weniger Gewicht als schlechte Technik.","knallhart":"{saetze}×{wdh}. Keine halben Wiederholungen. Wenn die letzten zwei nicht brennen, war das Gewicht Deko."},"workout_abschluss":{"standard":"Erledigt. Wieder ein Tag, an dem du drangeblieben bist.","knallhart":"Fertig. Die meisten hätten heute nach einem Grund gesucht, es kleiner zu machen. Du nicht."},"ruhetag":{"standard":"Heute ist Ruhetag. Erholung ist der Teil, in dem der Muskel tatsächlich wächst.","knallhart":"Ruhetag. Nicht dein Wunsch, sondern der Plan. Erholung ist kein Urlaub, sie ist Teil der Arbeit."},"verpasster_tag":{"standard":"Gestern ist ausgefallen. Kein Weltuntergang – mach heute die nächste Einheit.","knallhart":"Verpasst ist verpasst. Erklärungen ändern nichts. Heute zählt."},"deload_woche":{"standard":"Deload-Woche: halbe Satzzahl, gleiche Gewichte. Dein Körper holt sich zurück, was die letzten Wochen gekostet haben.","knallhart":"Deload. Halbe Sätze, gleiche Gewichte, volle Konzentration. Wer hier überzieht, zahlt nächsten Monat."},"block_abgeschlossen":{"standard":"Block abgeschlossen. Der nächste startet mit den Gewichten, die du dir erarbeitet hast.","knallhart":"Block durch. Neuer Block, gleiche Übungen, mehr Gewicht. So läuft das."},"level_up_angebot":{"standard":"Deine Zahlen steigen konstant. Willst du auf Fortgeschritten wechseln? Mehr Volumen, näher ans Limit.","knallhart":"Du bist dem Anfängerplan entwachsen. Fortgeschritten heißt mehr Volumen und weniger Puffer. Bereit?"},"streak_verloren":{"standard":"Streak zurück auf null. Die Arbeit der letzten Wochen bleibt trotzdem deine.","knallhart":"Streak weg. Die Zahl ist neu bei null, du nicht. Bau sie wieder auf."},"onboarding_willkommen":{"standard":"Willkommen bei unbroken. Ein paar Fragen, dann steht dein Plan.","knallhart":"Willkommen bei unbroken. Ein paar Fragen, dann gibt es keine Ausreden mehr."},"sicherheitshinweis_schmerz":{"standard":"Stechender Schmerz, Schwindel oder Druck in der Brust heißt: sofort abbrechen. Das gilt in jedem Ton.","knallhart":"Stechender Schmerz, Schwindel oder Druck in der Brust heißt: sofort abbrechen. Das gilt in jedem Ton."}},"tier":1}$cd$::jsonb),
  ('challenge_40_tage', 1, $cd${"id":"challenge_40_tage","tier":1,"name":"40 Days Unbroken","beschreibung":"40 Tage am Stück, Tag für Tag freigeschaltet. Trainingsstruktur wie der 4-Tage-Plan (Oberkörper/Unterkörper), zusätzlich jeden Tag eine Pflicht-Mental-Aufgabe – auch an Ruhetagen.","nutzt_split":"4tage","hinweis_plaene":"Die Trainingsinhalte kommen aus dem 4-Tage-Plan des jeweiligen Profils und Levels (fertige_plaene/<profil>/<level>_4tage.json). Die Challenge liefert nur Reihenfolge, Mental-Aufgaben und Meilensteine.","einstellungen":{"verpasster_tag_modus":{"standard":"soft","optionen":["soft","hardcore"],"soft":"Streak zurück auf 0, der Tag bleibt offen und wird nachgeholt.","hardcore":"Zurück auf Tag 1. Muss vor dem Start bewusst aktiviert werden und kann während der Challenge nicht mehr eingeschaltet werden."},"mental_aufgaben":"In der Challenge Pflicht, nicht abschaltbar. Ein Tag gilt erst als abgeschlossen, wenn Training (oder Ruhetag) und Mental-Aufgabe erledigt sind.","block_modifikatoren":"Die Wochenparameter (RIR, Deload) kommen aus dem Level. Bei Fortgeschritten fällt Woche 5 (Tag 29–35) auf die Deload-Woche – das ist so gewollt und wird im Text erklärt."},"tage":[{"tag":1,"woche":1,"typ":"training","vorlage":"U1","mental_aufgabe":{"text":"Schreib in drei Sätzen auf, warum du diese 40 Tage machst. Zettel aufheben – du brauchst ihn an Tag 20.","kategorie":"reflexion","pflicht":true},"meilenstein":null},{"tag":2,"woche":1,"typ":"training","vorlage":"L1","mental_aufgabe":{"text":"Die ersten 30 Minuten nach dem Aufwachen: kein Handy.","kategorie":"fokus","pflicht":true},"meilenstein":null},{"tag":3,"woche":1,"typ":"ruhe","vorlage":null,"mental_aufgabe":{"text":"Leg heute Abend alles für die nächste Einheit bereit: Klamotten, Flasche, Tasche.","kategorie":"vorbereitung","pflicht":true},"meilenstein":null},{"tag":4,"woche":1,"typ":"training","vorlage":"U2","mental_aufgabe":{"text":"Bett machen, direkt nach dem Aufstehen, vor allem anderen.","kategorie":"ordnung","pflicht":true},"meilenstein":null},{"tag":5,"woche":1,"typ":"training","vorlage":"L2","mental_aufgabe":{"text":"Schreib die Ausrede auf, die du diese Woche am häufigsten gedacht hast. Nur aufschreiben.","kategorie":"reflexion","pflicht":true},"meilenstein":null},{"tag":6,"woche":1,"typ":"ruhe","vorlage":null,"mental_aufgabe":{"text":"20 Minuten gehen – ohne Kopfhörer, ohne Handy in der Hand.","kategorie":"unbequem","pflicht":true},"meilenstein":null},{"tag":7,"woche":1,"typ":"ruhe","vorlage":null,"mental_aufgabe":{"text":"Accountability Mirror, Woche 1: eine Sache, die gut lief, eine, die schlecht lief, eine Ausrede.","kategorie":"reflexion","pflicht":true},"meilenstein":null},{"tag":8,"woche":2,"typ":"training","vorlage":"U1","mental_aufgabe":{"text":"Letzte 30 Sekunden der Dusche kalt (nur wenn du gesund bist).","kategorie":"unbequem","pflicht":true},"meilenstein":null},{"tag":9,"woche":2,"typ":"training","vorlage":"L1","mental_aufgabe":{"text":"Handy ab 22 Uhr außerhalb des Zimmers.","kategorie":"schlaf","pflicht":true},"meilenstein":null},{"tag":10,"woche":2,"typ":"ruhe","vorlage":null,"mental_aufgabe":{"text":"MEILENSTEIN – Cookie Jar: Schreib drei Dinge auf, die du in diesen 10 Tagen geschafft hast.","kategorie":"reflexion","pflicht":true},"meilenstein":{"standard":"Tag 10 geschafft. Die ersten zehn Tage sind die, an denen die meisten aussteigen – du nicht.","knallhart":"Tag 10. Der Reiz des Neuen ist jetzt weg. Ab hier trennt sich, wer es ernst meint."}},{"tag":11,"woche":2,"typ":"training","vorlage":"U2","mental_aufgabe":{"text":"Erledige eine Aufgabe, die seit über einer Woche liegen bleibt.","kategorie":"fokus","pflicht":true},"meilenstein":null},{"tag":12,"woche":2,"typ":"training","vorlage":"L2","mental_aufgabe":{"text":"Keine Social-Media-App vor 12 Uhr.","kategorie":"fokus","pflicht":true},"meilenstein":null},{"tag":13,"woche":2,"typ":"ruhe","vorlage":null,"mental_aufgabe":{"text":"Sprich heute eine Sache an, die du sonst runterschluckst – freundlich, aber klar.","kategorie":"unbequem","pflicht":true},"meilenstein":null},{"tag":14,"woche":2,"typ":"ruhe","vorlage":null,"mental_aufgabe":{"text":"Accountability Mirror, Woche 2: Was hat sich seit Woche 1 verändert?","kategorie":"reflexion","pflicht":true},"meilenstein":null},{"tag":15,"woche":3,"typ":"training","vorlage":"U1","mental_aufgabe":{"text":"Letzte 45 Sekunden der Dusche kalt.","kategorie":"unbequem","pflicht":true},"meilenstein":null},{"tag":16,"woche":3,"typ":"training","vorlage":"L1","mental_aufgabe":{"text":"Schreib eine Wenn-Dann-Regel für deinen größten Stolperstein und häng sie sichtbar auf.","kategorie":"reflexion","pflicht":true},"meilenstein":null},{"tag":17,"woche":3,"typ":"ruhe","vorlage":null,"mental_aufgabe":{"text":"Mach 15 Minuten lang etwas, bei dem du schlecht bist.","kategorie":"unbequem","pflicht":true},"meilenstein":null},{"tag":18,"woche":3,"typ":"training","vorlage":"U2","mental_aufgabe":{"text":"Heute keine Beschwerde laut aussprechen. Jedes Mal, wenn doch: 10 Kniebeugen.","kategorie":"fokus","pflicht":true},"meilenstein":null},{"tag":19,"woche":3,"typ":"training","vorlage":"L2","mental_aufgabe":{"text":"Räum eine Ecke oder Schublade auf, die dich seit Wochen nervt.","kategorie":"ordnung","pflicht":true},"meilenstein":null},{"tag":20,"woche":3,"typ":"ruhe","vorlage":null,"mental_aufgabe":{"text":"MEILENSTEIN – Halbzeit: Lies deinen Zettel von Tag 1 und schreib darunter, was sich verändert hat.","kategorie":"reflexion","pflicht":true},"meilenstein":{"standard":"Halbzeit. 20 Tage hinter dir, 20 vor dir. Du weißt jetzt, dass du es kannst.","knallhart":"Halbzeit. Die Hälfte ist kein Erfolg, sondern die Hälfte. Weiter."}},{"tag":21,"woche":3,"typ":"ruhe","vorlage":null,"mental_aufgabe":{"text":"30 Minuten ohne Bildschirm lesen oder etwas lernen.","kategorie":"fokus","pflicht":true},"meilenstein":null},{"tag":22,"woche":4,"typ":"training","vorlage":"U1","mental_aufgabe":{"text":"Steh heute exakt zur geplanten Zeit auf. Kein Snooze.","kategorie":"schlaf","pflicht":true},"meilenstein":null},{"tag":23,"woche":4,"typ":"training","vorlage":"L1","mental_aufgabe":{"text":"Hilf heute jemandem ungefragt – ohne es zu erwähnen.","kategorie":"charakter","pflicht":true},"meilenstein":null},{"tag":24,"woche":4,"typ":"ruhe","vorlage":null,"mental_aufgabe":{"text":"15 Minuten Mobility, ruhig und ohne Schmerz.","kategorie":"erholung","pflicht":true},"meilenstein":null},{"tag":25,"woche":4,"typ":"training","vorlage":"U2","mental_aufgabe":{"text":"Beim Training heute: Handy nur für den Plan, kein Scrollen zwischen den Sätzen.","kategorie":"fokus","pflicht":true},"meilenstein":null},{"tag":26,"woche":4,"typ":"training","vorlage":"L2","mental_aufgabe":{"text":"Schreib drei Dinge auf, die dir zuletzt Energie gezogen haben. Streich eines davon diese Woche.","kategorie":"reflexion","pflicht":true},"meilenstein":null},{"tag":27,"woche":4,"typ":"ruhe","vorlage":null,"mental_aufgabe":{"text":"Letzte 60 Sekunden der Dusche kalt.","kategorie":"unbequem","pflicht":true},"meilenstein":null},{"tag":28,"woche":4,"typ":"ruhe","vorlage":null,"mental_aufgabe":{"text":"Accountability Mirror, Woche 4: Wo bist du ehrlich gewesen, wo nicht?","kategorie":"reflexion","pflicht":true},"meilenstein":null},{"tag":29,"woche":5,"typ":"training","vorlage":"U1","mental_aufgabe":{"text":"Letzter Satz der letzten Übung: zwei saubere Wiederholungen mehr als geplant – nur solange die Technik hält.","kategorie":"unbequem","pflicht":true},"meilenstein":null},{"tag":30,"woche":5,"typ":"training","vorlage":"L1","mental_aufgabe":{"text":"MEILENSTEIN – Letzte 10 Tage: Schreib auf, wie du dich an Tag 40 fühlen willst.","kategorie":"reflexion","pflicht":true},"meilenstein":{"standard":"30 Tage. Nur noch zehn. Ab hier ziehst du es zu Ende, weil du angefangen hast.","knallhart":"30 Tage. Zehn übrig. Jetzt aufhören wäre die schlechteste Entscheidung der letzten fünf Wochen."}},{"tag":31,"woche":5,"typ":"ruhe","vorlage":null,"mental_aufgabe":{"text":"Einen ganzen Tag ohne Social Media.","kategorie":"fokus","pflicht":true},"meilenstein":null},{"tag":32,"woche":5,"typ":"training","vorlage":"U2","mental_aufgabe":{"text":"Mach heute die unangenehmste Aufgabe des Tages zuerst.","kategorie":"fokus","pflicht":true},"meilenstein":null},{"tag":33,"woche":5,"typ":"training","vorlage":"L2","mental_aufgabe":{"text":"Schreib einer Person, die dich unterstützt hat, eine ehrliche Nachricht.","kategorie":"charakter","pflicht":true},"meilenstein":null},{"tag":34,"woche":5,"typ":"ruhe","vorlage":null,"mental_aufgabe":{"text":"30 Minuten spazieren, danach fünf Minuten notieren, was dir durch den Kopf ging.","kategorie":"reflexion","pflicht":true},"meilenstein":null},{"tag":35,"woche":5,"typ":"ruhe","vorlage":null,"mental_aufgabe":{"text":"Accountability Mirror, Woche 5: Was machst du nach der Challenge weiter?","kategorie":"reflexion","pflicht":true},"meilenstein":null},{"tag":36,"woche":6,"typ":"training","vorlage":"U1","mental_aufgabe":{"text":"Cookie Jar: drei neue Einträge aus den letzten zwei Wochen.","kategorie":"reflexion","pflicht":true},"meilenstein":null},{"tag":37,"woche":6,"typ":"training","vorlage":"L1","mental_aufgabe":{"text":"Handy ab 21:30 Uhr aus dem Zimmer.","kategorie":"schlaf","pflicht":true},"meilenstein":null},{"tag":38,"woche":6,"typ":"ruhe","vorlage":null,"mental_aufgabe":{"text":"Bereite dein Finale vor: Zeit festlegen, Sachen bereitlegen, einer Person sagen, wann du Tag 40 trainierst.","kategorie":"vorbereitung","pflicht":true},"meilenstein":null},{"tag":39,"woche":6,"typ":"training","vorlage":"U2","mental_aufgabe":{"text":"Kein Snooze, kein Handy am Morgen, Bett gemacht – alle drei.","kategorie":"fokus","pflicht":true},"meilenstein":null},{"tag":40,"woche":6,"typ":"training","vorlage":"L2","mental_aufgabe":{"text":"FINALE – Nach dem Training: Schreib einen Brief an dein Ich von Tag 1.","kategorie":"reflexion","pflicht":true},"meilenstein":{"standard":"40 Tage. Abgeschlossen. Was du hier gelernt hast, gehört dir – schreib es in dein Cookie Jar.","knallhart":"40 Tage unbroken. Fertig. Und jetzt der eigentliche Test: Was machst du morgen?"}}]}$cd$::jsonb)
